insert into public.exercises (id, course_version_id, kind, slug, title, definition) values
  ('0660b26f-d024-5d1e-a03e-9e9b10ffebe5', 'a49c2a77-9fb5-5aae-aba1-bfb5249ed8f1', 'math', 'descriptive-stats-101-practice', 'Typical week: mean, median and spread: practice', '{"schemaVersion":1,"missionSlug":"descriptive-stats-101","datasets":[{"id":"store-a-weekly-pairs","title":"Store A: pairs sold per week, weeks 1 to 10","unit":"pairs","labels":["Wk 1","Wk 2","Wk 3","Wk 4","Wk 5","Wk 6","Wk 7","Wk 8","Wk 9","Wk 10"],"values":[132,148,141,155,139,150,146,158,144,312],"adjustable":{"index":9,"min":100,"max":400,"step":1,"label":"Week 10 (school reopening)"},"spread":"sample","decimals":1},{"id":"store-b-weekly-pairs","title":"Store B: pairs sold per week, weeks 1 to 9","unit":"pairs","labels":["Wk 1","Wk 2","Wk 3","Wk 4","Wk 5","Wk 6","Wk 7","Wk 8","Wk 9"],"values":[86,94,78,91,240,88,83,97,90],"adjustable":{"index":4,"min":50,"max":300,"step":1,"label":"Week 5 (bulk school order)"},"spread":"sample","decimals":1}],"practice":[{"id":"practice-mean-store-a","prompt":"Calculate the mean number of pairs Store A sold per week. Round to 1 decimal place.","datasetId":"store-a-weekly-pairs","statistic":"mean","decimals":1,"tolerance":{"kind":"absolute","value":0.05}},{"id":"practice-median-store-a","prompt":"Now find the median pairs sold per week for Store A.","datasetId":"store-a-weekly-pairs","statistic":"median","decimals":1,"tolerance":{"kind":"absolute","value":0.05}}]}'::jsonb),
  ('f8d2286b-18ae-507c-add9-c97cf4777735', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'article-prefix-left', 'Article prefixes with LEFT', '{"schemaVersion":1,"id":"article-prefix-left","version":1,"title":"Article prefixes with LEFT","objective":"Use LEFT to take the first characters of an article code and feed the result into a lookup.","instructions":"Each article code in column A starts with a two-letter category prefix and a six-character style code (for example SN-450). In B2:B7, extract the two-letter prefix with LEFT. In C2:C7, look the prefix in column B up in the category list in F1:G6 with XLOOKUP, showing the text \"Unknown\" when the prefix is not in the list. In D2:D7, extract the six-character style code with LEFT. Fix the category list with $ signs.","grid":{"rows":7,"cols":7},"starter":{"A1":"Article code","B1":"Category prefix","C1":"Category","D1":"Style code","F1":"Prefix","G1":"Category","A2":"SN-450-42","A3":"SD-120-38","A4":"bt-330-41","A5":"SS-210-44","A6":"XX-001-40","A7":"SL-075-39","F2":"SN","G2":"Sneaker","F3":"SD","G3":"Sandal","F4":"BT","G4":"Boot","F5":"SS","G5":"School shoe","F6":"SL","G6":"Slipper"},"editableCells":["B2","B3","B4","B5","B6","B7","C2","C3","C4","C5","C6","C7","D2","D3","D4","D5","D6","D7"],"allowedFunctions":["LEFT","XLOOKUP"],"hints":["LEFT(text, number_of_characters) returns characters from the start of the text. =LEFT(A2,2) gives the first two characters of A2.","The style code is the first six characters, so use LEFT(A2,6). For the category use =XLOOKUP(B2,$F$2:$F$6,$G$2:$G$6,\"Unknown\").","Matching ignores upper and lower case, so bt in a lower-case code still finds BT in the list. A prefix that is not in the list, like XX, returns the fourth argument."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('7b88e6cc-ef5d-5770-9b5e-e441edf7d4c5', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'averageif-region-average', 'Average sales per store by region', '{"schemaVersion":1,"id":"averageif-region-average","version":1,"title":"Average sales per store by region","objective":"Calculate the average per store for each region with AVERAGEIF and compare one region with the overall average.","instructions":"The sales list is in A1:C11. In F2:F4, use AVERAGEIF to find the average Sales (K) per store for the region named in E2:E4. Fix both ranges with $ signs and point the criteria at the region cell. In F5, use AVERAGE to find the average of all ten stores. In F6, subtract the all-store average (F5) from the Nairobi average (F2). Do not round; the answers may have decimals.","grid":{"rows":11,"cols":6},"starter":{"A1":"Store","B1":"Region","C1":"Sales (K)","E1":"Region","F1":"Average per store (K)","E2":"Nairobi","E3":"Mombasa","E4":"Kisumu","E5":"All stores","E6":"Nairobi minus all stores","A2":"Westlands","B2":"Nairobi","C2":"120","A3":"Nyali","B3":"Mombasa","C3":"85","A4":"Kondele","B4":"Kisumu","C4":"64","A5":"Karen","B5":"Nairobi","C5":"150","A6":"Bamburi","B6":"Mombasa","C6":"92","A7":"Eastleigh","B7":"Nairobi","C7":"98","A8":"Milimani","B8":"Kisumu","C8":"71","A9":"Likoni","B9":"Mombasa","C9":"110","A10":"Kibuye","B10":"Kisumu","C10":"58","A11":"Kilimani","B11":"Nairobi","C11":"135"},"editableCells":["F2","F3","F4","F5","F6"],"allowedFunctions":["AVERAGEIF","AVERAGE"],"hints":["AVERAGEIF has three parts: =AVERAGEIF(where to look, what to match, what to average).","For F2 look in the Region column ($B$2:$B$11), match E2 and average the Sales column ($C$2:$C$11). Copy the pattern for F3 and F4.","F5 is =AVERAGE(C2:C11), which ignores the regions. F6 is a simple subtraction: =F2-F5."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('9db5b7b5-b88e-5d80-8d49-c881ccd52c35', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'budget-actual-scorecard', 'Budget vs actual scorecard', '{"schemaVersion":1,"id":"budget-actual-scorecard","version":1,"title":"Budget vs actual scorecard","objective":"Calculate variance and variance %, flag stores outside tolerance and count the misses.","instructions":"B holds each store''s budget and C its actual sales, both in K. In D2:D6 calculate the variance (actual minus budget). In E2:E6 calculate the variance % (variance divided by budget, times 100) rounded to 1 decimal place with ROUND. In F2:F6 use ABS to show \"Miss\" when the variance % is more than the tolerance in I2 away from zero in either direction, otherwise \"On track\". In I3 use COUNTIF to count the stores flagged Miss.","grid":{"rows":6,"cols":9},"starter":{"A1":"Store","B1":"Budget (K)","C1":"Actual (K)","D1":"Variance (K)","E1":"Variance (%)","F1":"Flag","H2":"Tolerance (%)","H3":"Stores that missed","I2":"5","A2":"Nairobi","B2":"1200","C2":"1290","A3":"Mombasa","B3":"800","C3":"780","A4":"Kisumu","B4":"650","C4":"590","A5":"Nakuru","B5":"500","C5":"520","A6":"Eldoret","B6":"420","C6":"399"},"editableCells":["D2","D3","D4","D5","D6","E2","E3","E4","E5","E6","F2","F3","F4","F5","F6","I3"],"allowedFunctions":["ROUND","ABS","IF","COUNTIF"],"hints":["Variance is =C2-B2. Variance % is =ROUND(D2/B2*100,1).","ABS(E2) gives the size of the gap whichever way it goes. Compare it with $I$2 inside IF.","COUNTIF takes a range and a condition: the flags in F2:F6 and the text \"Miss\"."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('2858e2a0-14e6-5605-95ad-0e91df2311be', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'clean-lookup-messy-codes', 'Clean codes inside XLOOKUP', '{"schemaVersion":1,"id":"clean-lookup-messy-codes","version":1,"title":"Clean codes inside XLOOKUP","objective":"Combine TRIM and UPPER inside XLOOKUP so that messy codes match a clean price list.","instructions":"Order codes in column A were typed with stray spaces and mixed case. In B2:B7, build the clean code with TRIM and UPPER together (one formula, TRIM inside UPPER). In C2:C7, look up the price in the clean price list in E1:G6 with one XLOOKUP formula that cleans the code inside it with UPPER and TRIM, and show the text \"Not listed\" when the code is not on the list. Fix the price list with $ signs.","grid":{"rows":7,"cols":7},"starter":{"A1":"Code (as typed)","B1":"Clean code","C1":"Unit price (KES)","E1":"Code","F1":"Product","G1":"Price (KES)","A2":" sn-450","A3":"SD-120 ","A4":"bt-330","A5":"SL-075","A6":"gb-610","A7":"ss-210  ","E2":"SS-210","F2":"School shoe","G2":"2499","E3":"SN-450","F3":"Canvas sneaker","G3":"1999","E4":"SD-120","F4":"Ladies sandal","G4":"899","E5":"BT-330","F5":"Ankle boot","G5":"4599","E6":"SL-075","F6":"Slipper","G6":"499"},"editableCells":["B2","B3","B4","B5","B6","B7","C2","C3","C4","C5","C6","C7"],"allowedFunctions":["XLOOKUP","TRIM","UPPER"],"hints":["Functions can sit inside other functions. Excel works from the inside out, so UPPER(TRIM(A2)) removes the extra spaces first and then changes the letters to capitals.","Use the same cleaning as the first argument of XLOOKUP: =XLOOKUP(UPPER(TRIM(A2)),$E$2:$E$6,$G$2:$G$6,\"Not listed\").","A code that is genuinely not on the list, like GB-610, still ends as Not listed. Cleaning cannot create a price that does not exist."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('b4f28535-607d-52c0-8e13-e93794063e13', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'clearance-rule', 'A clearance decision with AND, OR and NOT', '{"schemaVersion":1,"id":"clearance-rule","version":1,"title":"A clearance decision with AND, OR and NOT","objective":"Combine NOT, AND and OR inside IF to build a clearance rule.","instructions":"In F2:F7 use NOT to show TRUE when the line has not yet been marked down (column E is not \"Yes\"). In G2:G7 show \"Clearance\" when ALL of these are true: the range is NOT \"Core\"; EITHER weeks in store is at least the limit in B9 OR sell-through is below the floor in B10; and the line is not yet marked down (column F). Otherwise show \"Keep\".","grid":{"rows":10,"cols":7},"starter":{"A1":"Item","B1":"Weeks in store","C1":"Sell-through","D1":"Range","E1":"Marked down?","F1":"Not yet marked down?","G1":"Decision","A2":"Sneakers","B2":"14","C2":"25%","D2":"Seasonal","E2":"No","A3":"Sandals","B3":"8","C3":"20%","D3":"Seasonal","E3":"No","A4":"Boots","B4":"20","C4":"15%","D4":"Core","E4":"No","A5":"School shoes","B5":"12","C5":"45%","D5":"Seasonal","E5":"No","A6":"Slippers","B6":"15","C6":"10%","D6":"Seasonal","E6":"Yes","A7":"Flip-flops","B7":"5","C7":"50%","D7":"Seasonal","E7":"No","A9":"Weeks-in-store limit","B9":"12","A10":"Sell-through floor","B10":"30%"},"editableCells":["F2","F3","F4","F5","F6","F7","G2","G3","G4","G5","G6","G7"],"allowedFunctions":["IF","AND","OR","NOT"],"hints":["NOT flips TRUE and FALSE. =NOT(E2=\"Yes\") is TRUE when E2 is anything other than Yes.","Build the decision from three parts inside AND: NOT(D2=\"Core\"), then OR(B2>=$B$9,C2<$B$10), then F2 (which already holds TRUE or FALSE).","Put it all in IF: =IF(AND(NOT(D2=\"Core\"),OR(B2>=$B$9,C2<$B$10),F2),\"Clearance\",\"Keep\"). The OR sits inside the AND."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('59f167a1-9ecd-5248-82dd-64d562b86a7f', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'commission-tier-if-chain', 'Commission tiers: a lookup with nested IF', '{"schemaVersion":1,"id":"commission-tier-if-chain","version":1,"title":"Commission tiers: a lookup with nested IF","objective":"Look up a value from a tier table with nested IF and absolute references (the v0 substitute for an approximate-match lookup).","instructions":"In C2:C5, return each rep''s commission rate from the tier table in F1:G4. Use the highest tier whose \"Sales from\" amount the rep has reached. Refer to the table cells (for example $G$3) instead of typing the rates.","grid":{"rows":5,"cols":7},"starter":{"A1":"Rep","B1":"Sales","C1":"Rate","A2":"Amina","B2":"42000","A3":"Brian","B3":"50000","A4":"Chao","B4":"87500","A5":"Dalia","B5":"125000","F1":"Sales from","G1":"Rate","F2":"0","G2":"2%","F3":"50000","G3":"4%","F4":"100000","G4":"6%"},"editableCells":["C2","C3","C4","C5"],"allowedFunctions":["IF"],"hints":["Check the highest tier first: =IF(B2>=$F$4, $G$4, ...).","Put a second IF in the value_if_false part for the middle tier, and use $G$2 as the last fallback.","The $ signs keep the table references fixed when you reuse the formula on the next row; B2 changes to B3."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('6e6133d7-aec9-5ce6-8bcc-e4b36fbf393c', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'countif-store-status', 'Store status counts', '{"schemaVersion":1,"id":"countif-store-status","version":1,"title":"Store status counts","objective":"Count stores by status with COUNTIF, using a criteria cell, a text criterion and a not-equal criterion.","instructions":"The store list is in A1:C11. In F2:F4, use COUNTIF on the Status column (C2:C11) to count the stores with the status named in E2:E4. Fix the range with $ signs and point the criteria at the cell in column E. In F5, count the stores that are not Open, using \"<>Open\". In F6, count the stores whose Region (B2:B11) is Kisumu by typing the text \"Kisumu\" in the formula.","grid":{"rows":11,"cols":6},"starter":{"A1":"Store","B1":"Region","C1":"Status","E1":"Question","F1":"Answer","E2":"Open","E3":"Closed","E4":"Renovation","E5":"Not open","E6":"Stores in Kisumu","A2":"Westlands","B2":"Nairobi","C2":"Open","A3":"Karen","B3":"Nairobi","C3":"Open","A4":"Eastleigh","B4":"Nairobi","C4":"Renovation","A5":"Nyali","B5":"Mombasa","C5":"Open","A6":"Bamburi","B6":"Mombasa","C6":"Closed","A7":"Likoni","B7":"Mombasa","C7":"open","A8":"Kondele","B8":"Kisumu","C8":"Open","A9":"Milimani","B9":"Kisumu","C9":"Closed","A10":"Nakuru CBD","B10":"Nakuru","C10":"Open","A11":"Eldoret CBD","B11":"Eldoret","C11":"Renovation"},"editableCells":["F2","F3","F4","F5","F6"],"allowedFunctions":["COUNTIF"],"hints":["COUNTIF has two parts: =COUNTIF(where to look, what to count).","For F2, look in the Status column $C$2:$C$11 and count the status in E2. Copy the same pattern for F3 and F4.","For F5 use the criteria \"<>Open\" in double quotes. For F6 look in the Region column $B$2:$B$11 and use \"Kisumu\". Some list entries use lower case; COUNTIF ignores case."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('6786f797-6e14-54b6-93b2-9710a6a83f6d', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'countifs-stock-bands', 'Stock bands with COUNTIFS', '{"schemaVersion":1,"id":"countifs-stock-bands","version":1,"title":"Stock bands with COUNTIFS","objective":"Count rows with two conditions on different columns, and with two conditions on the same column to build number bands from cells.","instructions":"The stock list is in A1:D13. In G2:G3, use COUNTIFS to count the lines whose Region (column B) matches column E and whose Category (column C) matches column F on the same row. In H6:H8, count the lines whose Pairs in stock (column D) are at least the number in column F and below the number in column G, building the criteria with & (for example \">=\"&F6). Use $ signs on the list ranges.","grid":{"rows":13,"cols":8},"starter":{"A1":"Line","B1":"Region","C1":"Category","D1":"Pairs in stock","E1":"Region","F1":"Category","G1":"Lines","E2":"Nairobi","F2":"Sneakers","E3":"Mombasa","F3":"Sandals","E5":"Stock band","F5":"At least","G5":"Below","H5":"Lines","E6":"Under 10 pairs","F6":"0","G6":"10","E7":"10 to 19 pairs","F7":"10","G7":"20","E8":"20 pairs or more","F8":"20","G8":"1000","A2":"1","B2":"Nairobi","C2":"Sneakers","D2":"8","A3":"2","B3":"Nairobi","C3":"Sandals","D3":"14","A4":"3","B4":"Nairobi","C4":"Sneakers","D4":"22","A5":"4","B5":"Mombasa","C5":"Sandals","D5":"5","A6":"5","B6":"Mombasa","C6":"Sneakers","D6":"10","A7":"6","B7":"Kisumu","C7":"School","D7":"19","A8":"7","B8":"Kisumu","C8":"Sneakers","D8":"20","A9":"8","B9":"Nairobi","C9":"School","D9":"35","A10":"9","B10":"Mombasa","C10":"Sandals","D10":"12","A11":"10","B11":"Kisumu","C11":"School","D11":"9","A12":"11","B12":"Nairobi","C12":"Sneakers","D12":"10","A13":"12","B13":"Mombasa","C13":"School","D13":"47"},"editableCells":["G2","G3","H6","H7","H8"],"allowedFunctions":["COUNTIFS"],"hints":["COUNTIFS takes pairs: =COUNTIFS(where to look 1, match 1, where to look 2, match 2).","For G2: =COUNTIFS($B$2:$B$13,E2,$C$2:$C$13,F2). Copy the pattern to G3.","For a band, use the Pairs column twice: =COUNTIFS($D$2:$D$13,\">=\"&F6,$D$2:$D$13,\"<\"&G6). Copy it down to H8."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('fa17612a-f1b9-5dac-a0b0-7f3baedf7913', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'discount-price-points', 'Discounted price points', '{"schemaVersion":1,"id":"discount-price-points","version":1,"title":"Discounted price points","objective":"Round a discounted price to the nearest KES 10 with ROUND, then subtract 1 to make a charm price.","instructions":"The discount rate is in B7. In D2:D5 work out the discounted price: list price times (1 minus the discount). In E2:E5 round the discounted price to the nearest KES 10. In F2:F5 make the charm price by subtracting 1 from the rounded price, so it ends in 9.","grid":{"rows":7,"cols":6},"starter":{"A1":"Item","B1":"List price (KES)","D1":"Discounted","E1":"Nearest 10","F1":"Charm price","A2":"Sneakers","B2":"1899","A3":"Sandals","B3":"749","A4":"Boots","B4":"2450","A5":"School shoes","B5":"1299","A7":"Discount","B7":"15%"},"editableCells":["D2","D3","D4","D5","E2","E3","E4","E5","F2","F3","F4","F5"],"allowedFunctions":["ROUND"],"hints":["The discounted price is the list price times (1 minus the discount). Use the discount cell with a dollar lock: =B2*(1-$B$7).","Round the discounted price, not the list price: =ROUND(D2,-1) rounds to the nearest 10.","The charm price is the rounded price minus 1: =E2-1. Always round first, then subtract."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('ff1d7951-80c7-5048-ad90-1c169962a572', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'exceptions-reorder-report', 'Reorder-point exceptions report', '{"schemaVersion":1,"id":"exceptions-reorder-report","version":1,"title":"Reorder-point exceptions report","objective":"Flag lines below reorder point with IF, then count them, find their share and total their value with COUNTIF, COUNT, COUNTIFS and SUMIFS.","instructions":"The stock list is in A1:F11. In E2:E11, show \"Yes\" when Pairs in stock (column C) is below the Reorder point (column D) on the same row, otherwise \"No\" (use IF). Then complete the report in H2:H6: H2 counts the lines flagged \"Yes\" (COUNTIF); H3 counts the lines in total (COUNT on column C); H4 is the share of lines below reorder point as a decimal, H2 divided by H3 (for example 0.25, not 25%); H5 counts the Nairobi lines flagged \"Yes\" (COUNTIFS); H6 adds the Stock value (K) in column F of the lines flagged \"Yes\" (SUMIFS). Use $ signs on the list ranges in H2:H6.","grid":{"rows":11,"cols":8},"starter":{"A1":"Line","B1":"Region","C1":"Pairs in stock","D1":"Reorder point","E1":"Below reorder?","F1":"Stock value (K)","G1":"Measure","H1":"Result","G2":"Lines below reorder point","G3":"Total lines","G4":"Share of lines below reorder point","G5":"Nairobi lines below reorder point","G6":"Stock value of lines below reorder point (K)","A2":"1","B2":"Nairobi","C2":"12","D2":"20","F2":"36","A3":"2","B3":"Nairobi","C3":"45","D3":"30","F3":"135","A4":"3","B4":"Nairobi","C4":"8","D4":"15","F4":"24","A5":"4","B5":"Mombasa","C5":"30","D5":"30","F5":"90","A6":"5","B6":"Mombasa","C6":"6","D6":"18","F6":"18","A7":"6","B7":"Mombasa","C7":"52","D7":"40","F7":"156","A8":"7","B8":"Kisumu","C8":"10","D8":"12","F8":"30","A9":"8","B9":"Kisumu","C9":"9","D9":"25","F9":"27","A10":"9","B10":"Nakuru","C10":"33","D10":"20","F10":"99","A11":"10","B11":"Eldoret","C11":"4","D11":"10","F11":"12"},"editableCells":["E2","E3","E4","E5","E6","E7","E8","E9","E10","E11","H2","H3","H4","H5","H6"],"allowedFunctions":["IF","COUNTIF","COUNT","COUNTIFS","SUMIFS"],"hints":["For E2 use =IF(C2<D2,\"Yes\",\"No\") and copy it down to E11. A line exactly on its reorder point is not below it.","H2 is =COUNTIF($E$2:$E$11,\"Yes\"). H3 is =COUNT($C$2:$C$11). H4 divides H2 by H3.","H5 needs two conditions: region Nairobi in $B$2:$B$11 and \"Yes\" in $E$2:$E$11. H6 adds $F$2:$F$11 where $E$2:$E$11 is \"Yes\"."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('6388ce9d-4b18-52bf-9d60-6fda4130ccd4', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'grade-discount-lookup', 'Discount by customer grade', '{"schemaVersion":1,"id":"grade-discount-lookup","version":1,"title":"Discount by customer grade","objective":"Look up each customer''s discount rate by grade, then work out the discount and the net order.","instructions":"In D2:D6 use XLOOKUP to find the grade in column B in the discount table H1:I5 and return the discount rate. If a grade is not in the table, return 0. Fix the table ranges with $ signs. In E2:E6 work out the discount in K (order value times the rate). In F2:F6 work out the net order in K (order value minus the discount).","grid":{"rows":6,"cols":9},"starter":{"A1":"Customer","B1":"Grade","C1":"Order value (K)","D1":"Discount rate","E1":"Discount (K)","F1":"Net order (K)","A2":"Kisumu Shoe Mart","B2":"A","C2":"800","A3":"Eldoret Footwear","B3":"B","C3":"650","A4":"Mombasa Sandals","B4":"C","C4":"420","A5":"Nakuru Kicks","B5":"b","C5":"300","A6":"Nairobi Walkers","B6":"E","C6":"500","H1":"Grade","I1":"Discount rate","H2":"A","I2":"0.1","H3":"B","I3":"0.07","H4":"C","I4":"0.04","H5":"D","I5":"0"},"editableCells":["D2","D3","D4","D5","D6","E2","E3","E4","E5","E6","F2","F3","F4","F5","F6"],"allowedFunctions":["XLOOKUP"],"hints":["The grade in B2 is the key. The grade labels are in H2:H5 and the rates are in I2:I5.","Use $ signs on the table ranges. =XLOOKUP(B2,$H$2:$H$5,$I$2:$I$5, ...) with a fourth argument.","The fourth argument is used for a grade that is not in the table. Use the number 0 so that the next formulas can still calculate.","E2 is the order value in C2 times the rate in D2. F2 is the order value minus the discount in E2."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('7bbc9b67-a6d1-5ce5-8c3f-b343dd33ea95', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'horizontal-month-lookup', 'Report any month from a row layout', '{"schemaVersion":1,"id":"horizontal-month-lookup","version":1,"title":"Report any month from a row layout","objective":"Look up sales and target for three report months across a row, then calculate variance and status.","instructions":"The report months are in B5:D5. In B6:D6 use XLOOKUP to find each month in the headings B1:G1 and return the sales from B2:G2. In B7:D7 return the target from B3:G3. In B8:D8 work out variance as sales minus target. In B9:D9 use IF to show the text \"On target\" when the variance is zero or more, otherwise \"Below target\". Use mixed references so the same formula works when copied across.","grid":{"rows":9,"cols":7},"starter":{"A1":"Month","B1":"Jan","C1":"Feb","D1":"Mar","E1":"Apr","F1":"May","G1":"Jun","A2":"Sales (K)","B2":"4200","C2":"3900","D2":"4650","E2":"4400","F2":"5100","G2":"4800","A3":"Target (K)","B3":"4500","C3":"4000","D3":"4500","E3":"4600","F3":"5000","G3":"5000","A5":"Report month","B5":"Mar","C5":"jun","D5":"feb","A6":"Sales (K)","A7":"Target (K)","A8":"Variance (K)","A9":"Status"},"editableCells":["B6","B7","B8","B9","C6","C7","C8","C9","D6","D7","D8","D9"],"allowedFunctions":["XLOOKUP","IF"],"hints":["The months are across row 1, so the lookup range is B1:G1 and the return range is a row too: B2:G2 for sales and B3:G3 for target.","For B6 start with =XLOOKUP(B5,$B$1:$G$1,$B$2:$G$2). Only the month cell should move when you copy across.","Use B$5 (with the $ before the 5) so the month always comes from row 5. Use $ signs on the whole table ranges.","Variance is B6-B7. For the status, test the variance: =IF(B8>=0,\"On target\",\"Below target\")."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('d3e774f4-b56e-559d-ba30-326b7470fc0e', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'if-business-thresholds', 'Stock reorder flags with IF', '{"schemaVersion":1,"id":"if-business-thresholds","version":1,"title":"Stock reorder flags with IF","objective":"Use IF with a comparison to flag a business threshold.","instructions":"In D2:D5, show \"Reorder\" when the stock on hand is at or below the reorder point, otherwise show \"OK\".","grid":{"rows":5,"cols":4},"starter":{"A1":"Item","B1":"On hand","C1":"Reorder point","D1":"Action","A2":"Sneakers","B2":"40","C2":"25","A3":"Sandals","B3":"12","C3":"20","A4":"Boots","B4":"30","C4":"30","A5":"School shoes","B5":"8","C5":"15"},"editableCells":["D2","D3","D4","D5"],"allowedFunctions":["IF"],"hints":["IF has three parts: =IF(condition, value_if_true, value_if_false).","\"At or below\" is the comparison <=.","Text results need double quotes, for example \"Reorder\"."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('3b7030e3-c116-57e0-b580-b2a5eb5f8e2e', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'label-join-ampersand', 'Labels and descriptions with &', '{"schemaVersion":1,"id":"label-join-ampersand","version":1,"title":"Labels and descriptions with &","objective":"Use the & operator to join cells and fixed text into a label and a full article description.","instructions":"Build two pieces of text for each article. In G2:G6, make a label in the form NBO-0123 | Canvas sneaker | 42: the store, a hyphen, the article number, then a space, a bar, a space, the product, a space, a bar, a space and the size. In H2:H6, make a description in the form Canvas sneaker - white, size 42, KES 1999: the product, a space, a hyphen, a space, the colour, a comma and a space, the word size, a space, the size, a comma and a space, KES, a space and the price. Join the pieces with & and put fixed text in double quotes.","grid":{"rows":6,"cols":8},"starter":{"A1":"Store","B1":"Article no.","C1":"Product","D1":"Colour","E1":"Size","F1":"Price (KES)","G1":"Label","H1":"Description","A2":"NBO","B2":"''0123","C2":"Canvas sneaker","D2":"white","E2":"42","F2":"1999","A3":"MSA","B3":"''0045","C3":"Ladies sandal","D3":"tan","E3":"38","F3":"899","A4":"KSM","B4":"''0330","C4":"Ankle boot","D4":"black","E4":"41","F4":"4599","A5":"NKU","B5":"''0210","C5":"School shoe","D5":"black","E5":"44","F5":"2499","A6":"ELD","B6":"''0075","C6":"Slipper","D6":"grey","E6":"39","F6":"499"},"editableCells":["G2","G3","G4","G5","G6","H2","H3","H4","H5","H6"],"allowedFunctions":[],"hints":["The & operator joins text. =A2&B2 puts the two cells side by side with nothing between them. Fixed text goes in double quotes: =A2&\"-\"&B2.","Spaces count, so a separator like \" | \" has a space before and after the bar, inside the quotes. For the label: =A2&\"-\"&B2&\" | \"&C2&\" | \"&E2.","Numbers join as text exactly as they appear, so 42 becomes 42 and 1999 becomes 1999. For the description: =C2&\" - \"&D2&\", size \"&E2&\", KES \"&F2."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('67fe1aef-b34e-56e8-85ed-f39a1fc0dc1b', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'loaded-cost-per-pair', 'Loaded cost per pair: brackets matter', '{"schemaVersion":1,"id":"loaded-cost-per-pair","version":1,"title":"Loaded cost per pair: brackets matter","objective":"Build a multi-step formula where brackets and the order of operations decide the answer.","instructions":"Each line shows the number of pairs ordered, the unit cost, the freight for the whole order and an example duty rate (0.25 means 25%). In F2:F5, work out the loaded cost per pair: the unit cost plus duty on the unit cost, plus the freight per pair (whole-order freight divided by the number of pairs). In G2:G5, work out the freight per pair as a share of the loaded cost per pair (a decimal, so 0.1 means 10%). Use brackets where they are needed.","grid":{"rows":5,"cols":7},"starter":{"A1":"Item","B1":"Pairs","C1":"Unit cost (KES)","D1":"Freight, whole order (KES)","E1":"Duty rate (example)","F1":"Loaded cost per pair (KES)","G1":"Freight share of loaded cost","A2":"Sneakers","B2":"200","C2":"1500","D2":"40000","E2":"0.25","A3":"Sandals","B3":"400","C3":"600","D3":"60000","E3":"0.25","A4":"Boots","B4":"100","C4":"3200","D4":"30000","E4":"0.2","A5":"School shoes","B5":"250","C5":"900","D5":"25000","E5":"0.1"},"editableCells":["F2","G2","F3","G3","F4","G4","F5","G5"],"allowedFunctions":[],"hints":["Unit cost plus duty is C2*(1+E2). The brackets make Excel add 1 and the rate before multiplying.","Freight per pair is D2/B2, so the loaded cost is =C2*(1+E2)+D2/B2. Multiplication and division are done before addition.","For G, divide the freight per pair by the loaded cost already in F2: =D2/B2/F2. Excel works left to right through / and *, so you do not need brackets here."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('4a48a81f-fa34-5484-94b9-0163c03e3b2d', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'lookup-error-handling', 'Sell-through with safe lookups', '{"schemaVersion":1,"id":"lookup-error-handling","version":1,"title":"Sell-through with safe lookups","objective":"Use if_not_found for missing codes and IFERROR for the sell-through division.","instructions":"Use the product list in G1:I6. In C2:C6 use XLOOKUP to return the opening stock for the code in column B, and in D2:D6 return the units sold. If a code is not on the list, show the text \"Not listed\" using the XLOOKUP fourth argument. Fix the list ranges with $ signs. In E2:E6 work out sell-through as units sold divided by opening stock, and use IFERROR so that any error shows the text \"n/a\".","grid":{"rows":6,"cols":9},"starter":{"A1":"Line","B1":"Product code","C1":"Opening stock","D1":"Units sold","E1":"Sell-through","A2":"1","B2":"SS-210","A3":"2","B3":"SN-450","A4":"3","B4":"ZZ-999","A5":"4","B5":"GB-610","A6":"5","B6":"bt-330","G1":"Code","H1":"Opening stock","I1":"Units sold","G2":"SS-210","H2":"80","I2":"60","G3":"SN-450","H3":"120","I3":"90","G4":"SD-120","H4":"50","I4":"40","G5":"BT-330","H5":"60","I5":"15","G6":"GB-610","H6":"0","I6":"0"},"editableCells":["C2","C3","C4","C5","C6","D2","D3","D4","D5","D6","E2","E3","E4","E5","E6"],"allowedFunctions":["XLOOKUP","IFERROR"],"hints":["Columns C and D use XLOOKUP. The code to find is in B2. The code column of the list is G2:G6, the stock column is H2:H6 and the units sold column is I2:I6.","Add \"Not listed\" as the fourth argument of XLOOKUP, and fix the list with $ signs, for example =XLOOKUP(B2,$G$2:$G$6,$H$2:$H$6,\"Not listed\").","Sell-through in E2 is units sold divided by opening stock, so D2/C2. Put it inside IFERROR as the first argument.","The second argument of IFERROR is what to show when there is an error: \"n/a\" in double quotes. Check line 3 (not on the list) and line 4 (zero stock)."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('5f3e0b31-f6c9-5ae7-b908-325d927a3eb6', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'lookup-margin-calc', 'Margin by product code', '{"schemaVersion":1,"id":"lookup-margin-calc","version":1,"title":"Margin by product code","objective":"Look up cost and price by code and calculate margin in KES and as a decimal share of the price.","instructions":"For each product code in A2:A6, use XLOOKUP and the product list G1:J6 to return the cost in B2:B6 and the selling price in C2:C6. Fix the list ranges with $ signs. In D2:D6 work out margin in KES (price minus cost). In E2:E6 work out margin as a share of the price (margin divided by price). Leave E as a decimal, for example 0.52.","grid":{"rows":6,"cols":10},"starter":{"A1":"Product code","B1":"Cost (KES)","C1":"Price (KES)","D1":"Margin (KES)","E1":"Margin %","A2":"bt-330","A3":"SS-210","A4":"SL-075","A5":"SD-120","A6":"SN-450","G1":"Code","H1":"Product","I1":"Cost (KES)","J1":"Price (KES)","G2":"SS-210","H2":"School shoe","I2":"1350","J2":"2499","G3":"SN-450","H3":"Canvas sneaker","I3":"1100","J3":"1999","G4":"SD-120","H4":"Ladies sandal","I4":"430","J4":"899","G5":"BT-330","H5":"Ankle boot","I5":"2600","J5":"4599","G6":"SL-075","H6":"Slipper","I6":"220","J6":"499"},"editableCells":["B2","B3","B4","B5","B6","C2","C3","C4","C5","C6","D2","D3","D4","D5","D6","E2","E3","E4","E5","E6"],"allowedFunctions":["XLOOKUP"],"hints":["Two XLOOKUPs per line: one for the cost and one for the price. Both use the code in column A as the key.","The code column in the list is G2:G6, the cost column is I2:I6 and the price column is J2:J6. Use $ signs on these ranges.","Margin in KES is the price minus the cost: C2-B2.","Margin percentage uses the margin divided by the price: D2/C2. Do not divide by the cost, that would be the mark-up."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('966d1866-c6c8-5a84-a70f-e743500a7ad4', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'markup-vs-margin', 'Mark-up and margin on four shoe lines', '{"schemaVersion":1,"id":"markup-vs-margin","version":1,"title":"Mark-up and margin on four shoe lines","objective":"Calculate mark-up (profit / cost) and margin (profit / price), and test the margin against a target with IF.","instructions":"Profit is price less cost. In D2:D5, work out the mark-up: profit divided by cost. In E2:E5, work out the margin: profit divided by price. Answers are decimals (0.07 means 7%). In F2:F5, show On target when the margin is at or above the target margin in G2, otherwise show Below target. Refer to G2 with $G$2 instead of typing the target.","grid":{"rows":5,"cols":7},"starter":{"A1":"Item","B1":"Cost (KES)","C1":"Price (KES)","D1":"Mark-up","E1":"Margin","F1":"Check","G1":"Target margin","G2":"0.3","A2":"Sneakers","B2":"1200","C2":"2000","A3":"Sandals","B3":"700","C3":"1000","A4":"Boots","B4":"2000","C4":"3500","A5":"School shoes","B5":"800","C5":"1000"},"editableCells":["D2","E2","F2","D3","E3","F3","D4","E4","F4","D5","E5","F5"],"allowedFunctions":["IF"],"hints":["Profit is price minus cost, so use brackets: =(C2-B2)/B2 for mark-up. The only thing that changes for margin is the number you divide by.","Margin divides the profit by the selling price: =(C2-B2)/C2.","For the check, compare the margin with the target: =IF(E2>=$G$2,\"On target\",\"Below target\"). >= means at or above."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('5672c8fd-3495-52df-8984-372e56148515', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'median-vs-average-weekly-sales', 'Average, median and the figure to report', '{"schemaVersion":1,"id":"median-vs-average-weekly-sales","version":1,"title":"Average, median and the figure to report","objective":"Compare AVERAGE and MEDIAN and let IF choose the fairer figure to report.","instructions":"B2:B9 holds eight weeks of sales in K for one store. Week 4 includes a one-off bulk order. In E2 work out the average, in E3 the median and in E4 the gap (average minus median). In E6 report the median when the gap is more than the skew limit (E5) multiplied by the median. Otherwise report the average.","grid":{"rows":9,"cols":5},"starter":{"A1":"Week","B1":"Sales (K)","D1":"Measure","E1":"Result","D2":"Average (K)","D3":"Median (K)","D4":"Gap (K)","D5":"Skew limit","E5":"0.1","D6":"Figure to report (K)","A2":"Wk 1","B2":"118","A3":"Wk 2","B3":"124","A4":"Wk 3","B4":"121","A5":"Wk 4","B5":"540","A6":"Wk 5","B6":"119","A7":"Wk 6","B7":"126","A8":"Wk 7","B8":"123","A9":"Wk 8","B9":"120"},"editableCells":["E2","E3","E4","E6"],"allowedFunctions":["AVERAGE","MEDIAN","IF"],"hints":["AVERAGE(B2:B9) and MEDIAN(B2:B9) both take the whole range of weekly sales.","The gap is the average minus the median: E2-E3 (or refer to the cells you filled).","Test the condition with E4>E5*E3. If TRUE return E3, if FALSE return E2."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('36247b80-4b66-5aa2-9049-6bc58125992e', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'order-total-lookup', 'Line totals and order total', '{"schemaVersion":1,"id":"order-total-lookup","version":1,"title":"Line totals and order total","objective":"Calculate each line total from a looked-up price and the quantity, then total the order.","instructions":"In D2:D6, work out each line total in KES: use XLOOKUP to find the unit price for the code in column B from the price list in F1:H7, then multiply by the quantity in column C. Fix the price list with $ signs. In D7, use SUM to add the five line totals.","grid":{"rows":7,"cols":8},"starter":{"A1":"Line","B1":"Product code","C1":"Quantity (pairs)","D1":"Line total (KES)","A2":"1","B2":"SN-450","C2":"12","A3":"2","B3":"SD-120","C3":"24","A4":"3","B4":"BT-330","C4":"6","A5":"4","B5":"SL-075","C5":"30","A6":"5","B6":"GB-610","C6":"10","C7":"Order total","F1":"Code","G1":"Product","H1":"Unit price (KES)","F2":"SS-210","G2":"School shoe","H2":"2499","F3":"SN-450","G3":"Canvas sneaker","H3":"1999","F4":"SD-120","G4":"Ladies sandal","H4":"899","F5":"BT-330","G5":"Ankle boot","H5":"4599","F6":"SL-075","G6":"Slipper","H6":"499","F7":"GB-610","G7":"Gumboot","H7":"1299"},"editableCells":["D2","D3","D4","D5","D6","D7"],"allowedFunctions":["XLOOKUP","SUM"],"hints":["A line total is unit price times quantity. You can write the lookup first and then add * and the quantity cell.","For D2 the formula starts =XLOOKUP(B2,$F$2:$F$7,$H$2:$H$7). The price list code column is F2:F7 and the price column is H2:H7.","Finish D2 with *C2 so the price is multiplied by the quantity, then copy the same pattern into D3:D6.","In D7, =SUM(D2:D6) adds the five line totals."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('d4f5f68f-2065-53a6-873d-7180bcc7d325', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'plan-variance-flags', 'Variance against plan with ABS', '{"schemaVersion":1,"id":"plan-variance-flags","version":1,"title":"Variance against plan with ABS","objective":"Work out variance, absolute variance and a flag when the gap is bigger than a tolerance.","instructions":"Plan is in column B and actual sales in column C, both in KES thousands (K). In D2:D6 work out the variance: actual minus plan. In E2:E6 work out the absolute variance, which is the size of the gap whether it is above or below plan. In F2:F6 show \"Check\" when the absolute variance is more than the tolerance in B8, otherwise \"OK\".","grid":{"rows":8,"cols":6},"starter":{"A1":"Store","B1":"Plan (K)","C1":"Actual (K)","D1":"Variance (K)","E1":"Absolute variance (K)","F1":"Flag","A2":"Nairobi","B2":"820","C2":"765","A3":"Mombasa","B3":"610","C3":"655","A4":"Kisumu","B4":"430","C4":"432","A5":"Nakuru","B5":"380","C5":"445","A6":"Eldoret","B6":"300","C6":"250","A8":"Tolerance (K)","B8":"50"},"editableCells":["D2","D3","D4","D5","D6","E2","E3","E4","E5","E6","F2","F3","F4","F5","F6"],"allowedFunctions":["ABS","IF"],"hints":["Variance is actual minus plan: =C2-B2. A negative result means the store is below plan.","ABS removes the sign: =ABS(D2) turns -12 into 12.","Use IF with the tolerance cell: =IF(E2>$B$8,\"Check\",\"OK\"). A gap exactly equal to the tolerance is still OK."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('fa14991b-41fc-5c33-8fba-d88dea87b717', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'region-or-bonus', 'Decisions where either condition is enough', '{"schemaVersion":1,"id":"region-or-bonus","version":1,"title":"Decisions where either condition is enough","objective":"Use OR inside IF so that a decision is made when at least one condition is true.","instructions":"In E2:E7 show \"Include\" when the region is \"Nairobi\" OR weekly sales are above the big-sales threshold in B9; otherwise show \"Skip\". In F2:F7 show \"Support\" when weekly sales are below the low-sales threshold in B10 OR sell-through is below the floor in B11; otherwise show \"OK\".","grid":{"rows":11,"cols":6},"starter":{"A1":"Store","B1":"Region","C1":"Weekly sales (K)","D1":"Sell-through","E1":"In regional report?","F1":"Needs support?","A2":"Westlands","B2":"Nairobi","C2":"480","D2":"55%","A3":"Nyali","B3":"Mombasa","C3":"620","D3":"62%","A4":"Kisumu Mall","B4":"Kisumu","C4":"350","D4":"35%","A5":"Nakuru Town","B5":"Nakuru","C5":"500","D5":"50%","A6":"Eldoret Hub","B6":"Eldoret","C6":"180","D6":"45%","A7":"CBD","B7":"Nairobi","C7":"150","D7":"30%","A9":"Big-sales threshold (K)","B9":"500","A10":"Low-sales threshold (K)","B10":"200","A11":"Sell-through floor","B11":"40%"},"editableCells":["E2","E3","E4","E5","E6","E7","F2","F3","F4","F5","F6","F7"],"allowedFunctions":["IF","OR"],"hints":["OR(test1, test2) is TRUE when at least one test is TRUE. Put it inside IF as the condition.","Text in a test needs double quotes: B2=\"Nairobi\". For E2: =IF(OR(B2=\"Nairobi\",C2>$B$9),\"Include\",\"Skip\").","For F2 use the low-sales and floor cells: =IF(OR(C2<$B$10,D2<$B$11),\"Support\",\"OK\"). Use the dollar locks so the formula copies down."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('ae0c41e5-a4ea-5558-81b0-966f1232d7b6', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'region-share-of-total', 'Each region''s share of total sales', '{"schemaVersion":1,"id":"region-share-of-total","version":1,"title":"Each region''s share of total sales","objective":"Work out a share of total as part divided by total, using an absolute reference for the total.","instructions":"B7 already holds the total sales of the five regions. In C2:C6, work out each region''s share of total: the region''s sales divided by the total in B7. Write the formula so you can copy it down without changing the reference to the total (use $B$7). Answers are decimals, so 0.07 means 7%. In C7, add up the five shares with SUM.","grid":{"rows":7,"cols":3},"starter":{"A1":"Region","B1":"Sales (K)","C1":"Share of total","A7":"Total","B7":"=SUM(B2:B6)","A2":"Nairobi","B2":"540","A3":"Mombasa","B3":"300","A4":"Kisumu","B4":"180","A5":"Nakuru","B5":"120","A6":"Eldoret","B6":"60"},"editableCells":["C2","C3","C4","C5","C6","C7"],"allowedFunctions":["SUM"],"hints":["A share is the part divided by the total: =B2/B7. Dividing, not multiplying by 100, gives a decimal such as 0.25.","Put $ signs on the total, =B2/$B$7, so it stays on B7 when you copy the formula down. B2 should still change to B3, B4 and so on.","In C7, use =SUM(C2:C6). Shares of a complete total always add up to the whole, which is 100%."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('e4540840-5a2c-54dc-b2aa-d2f30d683918', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'reorder-and-margin', 'Decisions that need two conditions', '{"schemaVersion":1,"id":"reorder-and-margin","version":1,"title":"Decisions that need two conditions","objective":"Use AND inside IF so that a decision is made only when every condition is true.","instructions":"In G2:G6 show \"Reorder\" only when stock on hand is below the reorder point AND the status is not \"Discontinued\"; otherwise show \"Hold\". In H2:H6 show \"Star\" only when the margin is above the margin target in B8 AND the sell-through is above the target in B9; otherwise show \"Review\".","grid":{"rows":9,"cols":8},"starter":{"A1":"Item","B1":"On hand","C1":"Reorder point","D1":"Status","E1":"Margin","F1":"Sell-through","G1":"Reorder?","H1":"Star line?","A2":"Sneakers","B2":"18","C2":"25","D2":"Active","E2":"45%","F2":"70%","A3":"Sandals","B3":"40","C3":"30","D3":"Active","E3":"50%","F3":"55%","A4":"Boots","B4":"10","C4":"20","D4":"Discontinued","E4":"38%","F4":"80%","A5":"School shoes","B5":"20","C5":"20","D5":"Active","E5":"42%","F5":"65%","A6":"Slippers","B6":"5","C6":"15","D6":"Active","E6":"40%","F6":"60%","A8":"Margin target","B8":"40%","A9":"Sell-through target","B9":"60%"},"editableCells":["G2","G3","G4","G5","G6","H2","H3","H4","H5","H6"],"allowedFunctions":["IF","AND"],"hints":["AND(test1, test2) is TRUE only when both tests are TRUE. Put it inside IF as the condition.","For G2: =IF(AND(B2<C2,D2<>\"Discontinued\"),\"Reorder\",\"Hold\"). <> means not equal to.","For H2 point at the target cells with dollar locks: =IF(AND(E2>$B$8,F2>$B$9),\"Star\",\"Review\"). Above a target means >, not >=."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('4dea5d2a-5bf5-5f76-a7d8-ea121e5c8fcb', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'reorder-quantity-floor', 'Reorder quantity floored at zero', '{"schemaVersion":1,"id":"reorder-quantity-floor","version":1,"title":"Reorder quantity floored at zero","objective":"Calculate a reorder quantity from a target cover and never return a negative number.","instructions":"B holds average weekly sales, C pairs on hand and D pairs on order for six styles. The target cover in weeks is in G2. In E2:E7 calculate the pairs to reorder: target weeks multiplied by weekly sales, minus on hand, minus on order. If the answer is negative, show 0. Use the MAX function for this.","grid":{"rows":7,"cols":7},"starter":{"A1":"Style","B1":"Avg weekly sales","C1":"On hand","D1":"On order","E1":"Reorder qty","F2":"Target cover (weeks)","G2":"6","A2":"Canvas sneaker","B2":"40","C2":"120","D2":"60","A3":"Ladies sandal","B3":"25","C3":"200","D3":"0","A4":"School shoe","B4":"30","C4":"45","D4":"50","A5":"Ankle boot","B5":"12","C5":"30","D5":"0","A6":"Slipper","B6":"18","C6":"40","D6":"100","A7":"Gumboot","B7":"35","C7":"20","D7":"120"},"editableCells":["E2","E3","E4","E5","E6","E7"],"allowedFunctions":["MAX","IF"],"hints":["The shortfall is $G$2*B2-C2-D2. The dollar signs lock the target cell.","A negative shortfall must become 0. MAX(0, shortfall) does that in one step.","Put the shortfall from the first hint inside MAX(0, ...), then copy the formula down to row 7."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('ce060f28-2ea6-5b40-af28-b4a8a31bfef9', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'return-column-picker', 'Price, cost and supplier by code', '{"schemaVersion":1,"id":"return-column-picker","version":1,"title":"Price, cost and supplier by code","objective":"Return three different columns of the product list for each order line, using the same key.","instructions":"For each order line, use the product code in column B as the key and the product list in G1:K6 as the source. In column C return the retail price, in column D the cost and in column E the supplier. Lookup and return ranges must have the same number of cells. Fix the ranges with $ signs.","grid":{"rows":6,"cols":11},"starter":{"A1":"Line","B1":"Product code","C1":"Retail price (KES)","D1":"Cost (KES)","E1":"Supplier","A2":"1","B2":"BT-330","A3":"2","B3":"sd-120","A4":"3","B4":"SS-210","A5":"4","B5":"SL-075","G1":"Code","H1":"Product","I1":"Retail price (KES)","J1":"Cost (KES)","K1":"Supplier","G2":"SS-210","H2":"School shoe","I2":"2499","J2":"1350","K2":"Thika Footwear","G3":"SN-450","H3":"Canvas sneaker","I3":"1999","J3":"1100","K3":"Nairobi Canvas Co","G4":"SD-120","H4":"Ladies sandal","I4":"899","J4":"430","K4":"Mombasa Leather","G5":"BT-330","H5":"Ankle boot","I5":"4599","J5":"2600","K5":"Nakuru Tanners","G6":"SL-075","H6":"Slipper","I6":"499","J6":"220","K6":"Eldoret Textiles"},"editableCells":["C2","C3","C4","C5","D2","D3","D4","D5","E2","E3","E4","E5"],"allowedFunctions":["XLOOKUP"],"hints":["Start with C2: =XLOOKUP(what to find, where to look, what to return). The code to find is in B2.","The code column in the product list is G2:G6. The retail price column is I2:I6, the cost column is J2:J6 and the supplier column is K2:K6.","Use $ signs on the list ranges, for example $G$2:$G$6 and $I$2:$I$6. The lookup range is the same in all three columns, only the return range changes.","Case does not matter: sd-120 finds SD-120. The text result in column E is the supplier name exactly as written in the list."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('e624bb0c-2ff1-599a-b2e2-d31d9c50daa8', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'round-price-list', 'Round a price list with ROUND', '{"schemaVersion":1,"id":"round-price-list","version":1,"title":"Round a price list with ROUND","objective":"Use ROUND with 2, 0 and -1 digits to round raw prices, and total the rounded prices.","instructions":"Column B holds raw prices in KES after a currency conversion. In C2:C5 round each price to 2 decimal places. In D2:D5 round to the nearest whole shilling. In E2:E5 round to the nearest KES 10. In D7 add up the whole-shilling prices from D2:D5 (not the raw prices).","grid":{"rows":7,"cols":5},"starter":{"A1":"Item","B1":"Raw price (KES)","C1":"2 decimals","D1":"Whole KES","E1":"Nearest 10","A2":"Sneakers","B2":"1249.456","A3":"Sandals","B3":"899.5","A4":"Boots","B4":"2374.25","A5":"School shoes","B5":"649.504","A7":"Total of whole-KES prices"},"editableCells":["C2","C3","C4","C5","D2","D3","D4","D5","E2","E3","E4","E5","D7"],"allowedFunctions":["ROUND","SUM"],"hints":["ROUND takes two arguments: =ROUND(number, digits). The first is the cell to round, for example B2.","2 digits keeps two decimals, 0 gives a whole number, and -1 rounds to the nearest 10.","For D7, add the rounded prices with =SUM(D2:D5). The total of rounded prices is not the same as the rounded total of raw prices."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('463bcca0-a28b-5879-93e1-6045ff7bc01e', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'safe-sell-through', 'Clean up divide-by-zero errors with IFERROR', '{"schemaVersion":1,"id":"safe-sell-through","version":1,"title":"Clean up divide-by-zero errors with IFERROR","objective":"Wrap a division in IFERROR so that a zero divisor shows a readable message instead of #DIV/0!.","instructions":"Sell-through is units sold divided by units received. In E2:E6 work it out, but show \"No stock\" when the division gives an error. Stock cover in weeks is stock left (received minus sold) divided by weekly unit sales. In F2:F6 work it out, but show \"No sales\" when the division gives an error. Sell-through is stored as a decimal, so 0.07 means 7%.","grid":{"rows":6,"cols":6},"starter":{"A1":"Store","B1":"Received (units)","C1":"Sold (units)","D1":"Weekly sales (units)","E1":"Sell-through","F1":"Stock cover (weeks)","A2":"Nairobi","B2":"400","C2":"260","D2":"40","A3":"Mombasa","B3":"0","C3":"0","D3":"0","A4":"Kisumu","B4":"250","C4":"175","D4":"25","A5":"Nakuru","B5":"300","C5":"90","D5":"0","A6":"Eldoret","B6":"150","C6":"60","D6":"12"},"editableCells":["E2","E3","E4","E5","E6","F2","F3","F4","F5","F6"],"allowedFunctions":["IFERROR"],"hints":["Start with the plain division: =C2/B2. For Mombasa it shows #DIV/0! because nothing was received.","IFERROR(value, value_if_error) shows the second argument when the first is an error: =IFERROR(C2/B2,\"No stock\").","For cover, put the whole division inside IFERROR: =IFERROR((B2-C2)/D2,\"No sales\"). The brackets make the subtraction happen first."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('85c671b6-f025-58ce-b056-dc9d3fa1248f', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'sell-through-slow-sellers', 'Sell-through % and slow-seller flags', '{"schemaVersion":1,"id":"sell-through-slow-sellers","version":1,"title":"Sell-through % and slow-seller flags","objective":"Calculate sell-through % safely and flag slow sellers.","instructions":"Columns B and C hold pairs sold and pairs on hand for six styles. In D2:D7 calculate the sell-through %: sold divided by (sold plus on hand), multiplied by 100, rounded to 1 decimal place with ROUND. If a style has no stock at all, use IFERROR to show 0 instead of an error. In E2:E7 show \"Slow\" when the sell-through is below the limit in G2, otherwise \"OK\".","grid":{"rows":7,"cols":7},"starter":{"A1":"Style","B1":"Sold","C1":"On hand","D1":"Sell-through (%)","E1":"Status","F2":"Slow-seller limit (%)","G2":"40","A2":"Canvas sneaker","B2":"180","C2":"120","A3":"Ladies sandal","B3":"45","C3":"155","A4":"School shoe","B4":"70","C4":"130","A5":"Ankle boot","B5":"33","C5":"67","A6":"Slipper","B6":"0","C6":"0","A7":"Gumboot","B7":"85","C7":"65"},"editableCells":["D2","D3","D4","D5","D6","D7","E2","E3","E4","E5","E6","E7"],"allowedFunctions":["IFERROR","ROUND","IF"],"hints":["Start with the plain formula: =B2/(B2+C2)*100. Then wrap it in ROUND(...,1).","Wrap the whole thing in IFERROR(...,0) so a style with no stock shows 0.","For the flag use =IF(D2<$G$2,\"Slow\",\"OK\") and copy it down. The $ signs keep the limit cell fixed."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('339e96a9-f68a-5fa8-aade-e59e7c4846e4', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'size-curve-share', 'Size-curve shares and the top size', '{"schemaVersion":1,"id":"size-curve-share","version":1,"title":"Size-curve shares and the top size","objective":"Calculate each size''s share of total pairs and find the biggest size.","instructions":"A2:A8 are shoe sizes and B2:B8 are pairs sold. In B9 add up the pairs sold. In C2:C8 work out each size''s share of the total as a percentage (pairs divided by the total in B9, times 100), rounded to 1 decimal place with ROUND. Use absolute references so the formula can be copied down. In F2 find the most pairs sold in one size, in F3 use XLOOKUP to find which size that is, and in F4 find the largest share.","grid":{"rows":9,"cols":6},"starter":{"A1":"Size","B1":"Pairs sold","C1":"Share (%)","A9":"Total","E1":"Summary","E2":"Most pairs in one size","E3":"Size that sells most","E4":"Its share (%)","A2":"38","B2":"14","A3":"39","B3":"26","A4":"40","B4":"48","A5":"41","B5":"62","A6":"42","B6":"55","A7":"43","B7":"31","A8":"44","B8":"14"},"editableCells":["B9","C2","C3","C4","C5","C6","C7","C8","F2","F3","F4"],"allowedFunctions":["SUM","ROUND","MAX","XLOOKUP"],"hints":["B9 is =SUM(B2:B8). Each share is =B2/$B$9*100 with the total locked by dollar signs.","Wrap the share in ROUND(...,1). F2 is MAX over the pairs column and F4 is MAX over the share column.","For F3 look up F2 in B2:B8 and return from A2:A8: XLOOKUP(lookup value, lookup range, return range)."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('3c898039-9ca7-5e1b-abba-52623477cd0c', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'size-run-lookup', 'Size run and price by size', '{"schemaVersion":1,"id":"size-run-lookup","version":1,"title":"Size run and price by size","objective":"Look up the size run and the unit price for each order line, using the size as the key.","instructions":"For each order line, use XLOOKUP with the size wanted in column B as the key and the size table in F1:H10 as the source. In C2:C6 return the pairs in the size run (column G). In D2:D6 return the unit price (column H). Fix the table ranges with $ signs. If a size is not in the table, show the text \"Not stocked\" in both columns.","grid":{"rows":10,"cols":8},"starter":{"A1":"Line","B1":"Size wanted (EU)","C1":"Pairs in size run","D1":"Unit price (KES)","A2":"1","B2":"38","A3":"2","B3":"41","A4":"3","B4":"36","A5":"4","B5":"44","A6":"5","B6":"47","F1":"Size (EU)","G1":"Pairs in size run","H1":"Price (KES)","F2":"36","G2":"4","H2":"2199","F3":"37","G3":"6","H3":"2199","F4":"38","G4":"10","H4":"2299","F5":"39","G5":"14","H5":"2299","F6":"40","G6":"16","H6":"2399","F7":"41","G7":"12","H7":"2399","F8":"42","G8":"8","H8":"2499","F9":"43","G9":"6","H9":"2499","F10":"44","G10":"4","H10":"2599"},"editableCells":["C2","C3","C4","C5","C6","D2","D3","D4","D5","D6"],"allowedFunctions":["XLOOKUP"],"hints":["XLOOKUP has three parts and one optional part: =XLOOKUP(what to find, where to look, what to return, [if not found]).","For C2, find B2 in the Size column F2:F10 and return the matching cell from the Pairs column G2:G10. For D2, use the same key but return from H2:H10.","Write the table ranges with $ signs ($F$2:$F$10, $G$2:$G$10, $H$2:$H$10) so they do not move when you copy the formula down. Only B2 should change from row to row.","Add \"Not stocked\" in double quotes as the fourth argument so a missing size shows that text instead of #N/A."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('3e024f52-8f74-5ba8-a3f5-914884991279', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'size-suffix-right', 'Size suffix with RIGHT', '{"schemaVersion":1,"id":"size-suffix-right","version":1,"title":"Size suffix with RIGHT","objective":"Use RIGHT to take the size from the end of an article code, convert it to a number, and look up the pairs in stock.","instructions":"Each article code in column A ends with a two-digit size. In B2:B6, extract the size with RIGHT. RIGHT returns text, so in C2:C6 turn the text size in column B into a number by multiplying it by 1. In D2:D6, look up the number in column C in the stock list in F1:G7 with XLOOKUP and show the text \"No stock\" when the size is not in the list. Fix the stock list with $ signs.","grid":{"rows":7,"cols":7},"starter":{"A1":"Article code","B1":"Size (text)","C1":"Size (number)","D1":"Pairs in stock","F1":"Size","G1":"Pairs in stock","A2":"SN-450-42","A3":"SD-120-38","A4":"BT-330-41","A5":"SS-210-44","A6":"SL-075-39","F2":"38","G2":"6","F3":"39","G3":"4","F4":"40","G4":"9","F5":"41","G5":"3","F6":"42","G6":"7","F7":"43","G7":"2"},"editableCells":["B2","B3","B4","B5","B6","C2","C3","C4","C5","C6","D2","D3","D4","D5","D6"],"allowedFunctions":["RIGHT","XLOOKUP"],"hints":["RIGHT(text, number_of_characters) returns characters from the end of the text. =RIGHT(A2,2) gives the last two characters of A2.","RIGHT gives text, so \"42\" is not the number 42. Multiplying by 1 (=B2*1) turns numeric-looking text into a real number.","XLOOKUP never matches text with a number. Look up the number column C, not the text column B: =XLOOKUP(C2,$F$2:$F$7,$G$2:$G$7,\"No stock\")."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('664aea18-8996-5de2-a97c-f71da89977f0', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'sku-key-build', 'Standard SKU key and duplicate check', '{"schemaVersion":1,"id":"sku-key-build","version":1,"title":"Standard SKU key and duplicate check","objective":"Build a standard SKU key such as SNE-450-42 from a category name, a style number and a size, then flag duplicate keys.","instructions":"The standard SKU key is: the first three letters of the category in capitals, a hyphen, the style number padded to three digits with leading zeros, a hyphen and the size (for example SNE-450-42, or SAN-045-38 for style 45). In D2:D7, build the key from columns A, B and C. Clean the category with TRIM first, use LEFT for the three letters and UPPER for capitals, and pad the style number with RIGHT(\"000\"&B2,3). In E2:E7, show Duplicate when the same key appears more than once in D2:D7 and Unique when it does not, using IF and COUNTIF. Fix the key range with $ signs.","grid":{"rows":7,"cols":5},"starter":{"A1":"Category (as typed)","B1":"Style no.","C1":"Size","D1":"SKU key","E1":"Duplicate check","A2":"Sneaker","B2":"450","C2":"42","A3":" sandal","B3":"45","C3":"38","A4":"BOOT ","B4":"330","C4":"41","A5":"sneaker","B5":"450","C5":"42","A6":"Slipper","B6":"7","C6":"39","A7":"School shoe","B7":"210","C7":"44"},"editableCells":["D2","D3","D4","D5","D6","D7","E2","E3","E4","E5","E6","E7"],"allowedFunctions":["TRIM","UPPER","LEFT","RIGHT","IF","COUNTIF"],"hints":["Build the key in parts and join them with &. Part 1: UPPER(LEFT(TRIM(A2),3)). Part 2: RIGHT(\"000\"&B2,3). Part 3: C2. Put \"-\" between them.","To pad the style number, join 000 in front and keep the last three characters: RIGHT(\"000\"&B2,3) turns 45 into 045 and 450 into 450 (the zeros in front are cut off).","COUNTIF(range, value) counts how many cells in the range equal the value. Each key counts itself once, so a key that is unique has a count of 1. Test for more than one: =IF(COUNTIF($D$2:$D$7,D2)>1,\"Duplicate\",\"Unique\")."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('268f0cb3-c10d-5ecf-a799-76f61c831ea9', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'sku-length-check-len', 'SKU length check with LEN', '{"schemaVersion":1,"id":"sku-length-check-len","version":1,"title":"SKU length check with LEN","objective":"Count the characters in each SKU code with LEN, then use IF with LEN to flag codes that are not the standard length.","instructions":"The standard SKU length is in F1. In B2:B7, show the length of each SKU code in column A. In C2:C7, show OK when the length equals the standard length in F1 and Check when it does not. Do the check in one formula that uses IF and LEN together, and fix F1 with $ signs so the formula can be copied down.","grid":{"rows":7,"cols":6},"starter":{"A1":"SKU code","B1":"Length","C1":"Check","E1":"Standard length","F1":"9","A2":"SN-450-42","A3":"SD-120-38","A4":"BT-33-40","A5":"SS-210-411","A6":"SL-075-4","A7":"CV-880-43"},"editableCells":["B2","B3","B4","B5","B6","B7","C2","C3","C4","C5","C6","C7"],"allowedFunctions":["LEN","IF"],"hints":["LEN counts every character in a cell: letters, digits, hyphens and spaces. =LEN(A2) gives the length of the code in A2.","For the check, compare the length with the standard length: IF(LEN(A2)=$F$1, \"OK\", \"Check\"). The text results go in double quotes.","Use $F$1 (with both $ signs) so every row compares with the same standard length when you copy the formula down. Then change F1 to see the flags update."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('48d5c0f3-07b6-52a2-bdc6-8aeb5c3455cd', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'stock-count-progress', 'Stock count progress with COUNT', '{"schemaVersion":1,"id":"stock-count-progress","version":1,"title":"Stock count progress with COUNT","objective":"Use COUNT to count the cells that hold numbers, and use the result in a calculation.","instructions":"A stock count is in progress. Column A numbers the 10 lines in the list. Column C holds the pairs counted so far: some lines hold text such as n/a or TBC, and some are still empty. Fill F2:F5. F2: how many lines are in the list (count the numbers in A2:A11). F3: how many lines have a number in C2:C11. F4: how many lines are still to be counted (list less counted). F5: the average pairs per counted line, worked out as the total pairs divided by the number of counted lines.","grid":{"rows":11,"cols":6},"starter":{"A1":"Line no.","B1":"Style","C1":"Pairs counted","E1":"Measure","F1":"Result","E2":"Lines in the list","E3":"Lines counted","E4":"Lines still to count","E5":"Average pairs per counted line","A2":"1","B2":"SH-101","C2":"24","A3":"2","B3":"SH-102","C3":"0","A4":"3","B4":"SH-103","C4":"n/a","A5":"4","B5":"SH-104","C5":"15","A6":"5","B6":"SH-105","A7":"6","B7":"SH-106","C7":"40","A8":"7","B8":"SH-107","C8":"TBC","A9":"8","B9":"SH-108","C9":"8","A10":"9","B10":"SH-109","A11":"10","B11":"SH-110","C11":"33"},"editableCells":["F2","F3","F4","F5"],"allowedFunctions":["COUNT","SUM","AVERAGE"],"hints":["COUNT counts only the cells that contain numbers. Text and empty cells are ignored: =COUNT(C2:C11).","F4 is a subtraction using the two cells above it: =F2-F3.","For F5, divide a total by a count: =SUM(C2:C11)/F3. A zero counts as a counted line because 0 is a number."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('28455a7c-737c-5b41-9232-b21548a42a11', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'stock-cover-weeks-status', 'Stock cover and status labels', '{"schemaVersion":1,"id":"stock-cover-weeks-status","version":1,"title":"Stock cover and status labels","objective":"Calculate stock cover in weeks and label each style against two limits.","instructions":"For six styles, B holds pairs on hand and C holds average weekly sales. In D2:D7 calculate cover in weeks (on hand divided by weekly sales) rounded to 1 decimal place with ROUND. If weekly sales are 0, use IFERROR to show the text No sales. In E2:E7 show \"Check\" when D says No sales, \"Low\" when cover is below the limit in G2, \"Overstock\" when cover is above the limit in G3, otherwise \"OK\".","grid":{"rows":7,"cols":7},"starter":{"A1":"Style","B1":"On hand","C1":"Avg weekly sales","D1":"Cover (weeks)","E1":"Status","F2":"Low if under (weeks)","G2":"4","F3":"Overstock if over (weeks)","G3":"12","A2":"Canvas sneaker","B2":"120","C2":"40","A3":"Ladies sandal","B3":"300","C3":"25","A4":"School shoe","B4":"150","C4":"30","A5":"Ankle boot","B5":"210","C5":"12","A6":"Slipper","B6":"80","C6":"0","A7":"Gumboot","B7":"100","C7":"35"},"editableCells":["D2","D3","D4","D5","D6","D7","E2","E3","E4","E5","E6","E7"],"allowedFunctions":["IFERROR","ROUND","IF"],"hints":["Cover is on hand divided by weekly sales: =B2/C2. Wrap it in ROUND(...,1).","Put the whole thing inside IFERROR(...,\"No sales\") to catch the zero-sales row.","For the label nest two or three IFs, for example =IF(D2=\"No sales\",\"Check\",IF(D2<$G$2,\"Low\",IF(...)))."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('2126212c-5f9e-56a9-a9c8-ffb8c2051acb', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'stock-status-labels', 'Stock status labels with nested IF', '{"schemaVersion":1,"id":"stock-status-labels","version":1,"title":"Stock status labels with nested IF","objective":"Build a four-way status label with nested IF and AND, then turn the label into an action.","instructions":"In E2:E7 show the stock status. Use \"Out of stock\" when on hand is 0. Otherwise use \"OK\" when on hand is at least the minimum (column C) and at most the maximum (column D). Otherwise use \"Low\" when on hand is below the minimum, and \"Overstock\" for everything else. In F2:F7 show \"Reorder\" for Out of stock or Low, \"Markdown\" for Overstock and \"None\" for OK. Spell the labels exactly as written.","grid":{"rows":7,"cols":6},"starter":{"A1":"Item","B1":"On hand","C1":"Minimum","D1":"Maximum","E1":"Status","F1":"Action","A2":"Sneakers","B2":"0","C2":"20","D2":"60","A3":"Sandals","B3":"12","C3":"20","D3":"60","A4":"Boots","B4":"20","C4":"20","D4":"60","A5":"School shoes","B5":"60","C5":"20","D5":"60","A6":"Slippers","B6":"85","C6":"20","D6":"60","A7":"Flip-flops","B7":"35","C7":"15","D7":"50"},"editableCells":["E2","E3","E4","E5","E6","E7","F2","F3","F4","F5","F6","F7"],"allowedFunctions":["IF","AND","OR"],"hints":["Test the zero case first: =IF(B2=0,\"Out of stock\", ...). IF stops at the first test that is TRUE, so order matters.","Put another IF in the false branch. The OK test needs AND: AND(B2>=C2,B2<=D2) is TRUE when stock is between the minimum and the maximum.","Full formula: =IF(B2=0,\"Out of stock\",IF(AND(B2>=C2,B2<=D2),\"OK\",IF(B2<C2,\"Low\",\"Overstock\"))). For F2 use OR: =IF(OR(E2=\"Out of stock\",E2=\"Low\"),\"Reorder\",IF(E2=\"Overstock\",\"Markdown\",\"None\"))."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('9c2dd13a-9158-5a8b-a5db-344b50779677', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'store-code-case', 'Store codes with UPPER and LOWER', '{"schemaVersion":1,"id":"store-code-case","version":1,"title":"Store codes with UPPER and LOWER","objective":"Use UPPER and LOWER to put codes into one standard case, then look up each store''s region.","instructions":"Store codes in column A were typed in mixed case. In B2:B6, show each code in capitals with UPPER. In C2:C6, show each code in lower case with LOWER. In D2:D6, look up the standard code from column B in the store list in F1:G6 with XLOOKUP and show the text \"Unknown\" when the code is not in the list. Fix the store list with $ signs.","grid":{"rows":6,"cols":7},"starter":{"A1":"Store code (as typed)","B1":"Standard code","C1":"Lower-case key","D1":"Region","F1":"Code","G1":"Region","A2":"nbo-01","A3":"Msa-02","A4":"KSM-03","A5":"nku-04","A6":"Eld-05","F2":"NBO-01","G2":"Nairobi","F3":"MSA-02","G3":"Mombasa","F4":"KSM-03","G4":"Kisumu","F5":"NKU-04","G5":"Nakuru","F6":"ELD-05","G6":"Eldoret"},"editableCells":["B2","B3","B4","B5","B6","C2","C3","C4","C5","C6","D2","D3","D4","D5","D6"],"allowedFunctions":["UPPER","LOWER","XLOOKUP"],"hints":["UPPER(text) turns every letter into a capital and LOWER(text) into a small letter. Digits and hyphens do not change. =UPPER(A2) gives NBO-01 for nbo-01.","Use UPPER in column B and LOWER in column C, both pointing at the original code in column A.","For the region, look up the standard code in B2: =XLOOKUP(B2,$F$2:$F$6,$G$2:$G$6,\"Unknown\"). Fix the list ranges with $ signs."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('863de966-2d12-5caf-aa99-f927917920fb', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'store-growth-vs-last-year', 'Growth versus last year with a zero guard', '{"schemaVersion":1,"id":"store-growth-vs-last-year","version":1,"title":"Growth versus last year with a zero guard","objective":"Calculate percentage change as (this year - last year) / last year, and guard against a last year of zero with IF.","instructions":"In D2:D6, work out each store''s growth: this year less last year, divided by last year. The answer is a decimal, so 0.07 means 7% growth and -0.07 means a 7% fall. A store with no sales last year (last year is 0) cannot be divided by, so for that store show the text New instead. Use one formula that works for every row.","grid":{"rows":6,"cols":4},"starter":{"A1":"Store","B1":"Last year (K)","C1":"This year (K)","D1":"Growth","A2":"Nairobi","B2":"800","C2":"900","A3":"Mombasa","B3":"500","C3":"450","A4":"Kisumu","B4":"320","C4":"320","A5":"Nakuru","B5":"250","C5":"325","A6":"Eldoret (new store)","B6":"0","C6":"90"},"editableCells":["D2","D3","D4","D5","D6"],"allowedFunctions":["IF"],"hints":["Growth is the change divided by last year: =(C2-B2)/B2. Put the subtraction in brackets so it happens first.","If B2 is 0, the division gives #DIV/0!. Test for it first: =IF(B2=0, \"New\", ...).","Put the growth calculation in the value_if_false part: =IF(B2=0,\"New\",(C2-B2)/B2). Then copy the same pattern to every row."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('bea85617-132b-5160-9244-b9ec90e17104', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'store-scorecard-capstone', 'Store scorecard capstone', '{"schemaVersion":1,"id":"store-scorecard-capstone","version":1,"title":"Store scorecard capstone","objective":"Combine SUMIFS, COUNTIFS, XLOOKUP, ROUND and IF into a one-row-per-store scorecard.","instructions":"A1:C13 is a weekly sales log in K, E1:F4 is a table of store targets and I7:I10 holds the rules. For each store in H2:H4 fill the scorecard: I total sales (SUMIFS on the log), J good weeks (COUNTIFS of the store''s weeks with sales at or above the good-week level in I7), K target (XLOOKUP in the target table), L achievement % (total divided by target, times 100, rounded to 1 decimal place) and M rating. Rating is \"Star\" when achievement is at or above I9 and good weeks are at least I8; otherwise \"Watch\" when achievement is at or above I10; otherwise \"Action\".","grid":{"rows":13,"cols":13},"starter":{"A1":"Store","B1":"Week","C1":"Sales (K)","E1":"Store","F1":"Target (K)","H1":"Store","I1":"Total sales (K)","J1":"Good weeks","K1":"Target (K)","L1":"Achievement (%)","M1":"Rating","H6":"Rules (inputs)","H7":"Good week from (K)","I7":"100","H8":"Star needs good weeks","I8":"3","H9":"Star at (%)","I9":"100","H10":"Watch at (%)","I10":"90","A2":"Nairobi","B2":"Wk 1","C2":"120","A3":"Mombasa","B3":"Wk 1","C3":"90","A4":"Kisumu","B4":"Wk 1","C4":"70","A5":"Nairobi","B5":"Wk 2","C5":"135","A6":"Mombasa","B6":"Wk 2","C6":"105","A7":"Kisumu","B7":"Wk 2","C7":"82","A8":"Nairobi","B8":"Wk 3","C8":"110","A9":"Mombasa","B9":"Wk 3","C9":"98","A10":"Kisumu","B10":"Wk 3","C10":"75","A11":"Nairobi","B11":"Wk 4","C11":"95","A12":"Mombasa","B12":"Wk 4","C12":"102","A13":"Kisumu","B13":"Wk 4","C13":"66","E2":"Nairobi","F2":"440","H2":"Nairobi","E3":"Mombasa","F3":"420","H3":"Mombasa","E4":"Kisumu","F4":"380","H4":"Kisumu"},"editableCells":["I2","J2","K2","L2","M2","I3","J3","K3","L3","M3","I4","J4","K4","L4","M4"],"allowedFunctions":["SUMIFS","COUNTIFS","XLOOKUP","ROUND","AND","IF"],"hints":["Total: =SUMIFS($C$2:$C$13,$A$2:$A$13,H2). Good weeks: COUNTIFS with the store test and the condition \">=\"&$I$7.","Target: =XLOOKUP(H2,$E$2:$E$4,$F$2:$F$4). Achievement: =ROUND(I2/K2*100,1).","Rating: an IF containing AND(L2>=$I$9,J2>=$I$8) for Star, then a second IF for Watch against $I$10, with Action as the last value."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('f29fb661-2afe-575c-ab07-ff25c4ae5d0c', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'store-weekly-sales-stats', 'Four weeks of store sales: average, best and weakest', '{"schemaVersion":1,"id":"store-weekly-sales-stats","version":1,"title":"Four weeks of store sales: average, best and weakest","objective":"Use AVERAGE, MAX and MIN to summarise a row of weekly sales.","instructions":"For each store (rows 2 to 5), the four weekly sales figures are in columns B to E, in KES thousands (K). In column F, work out the average weekly sales. In column G, find the best week. In column H, find the weakest week. Each formula should read the four weeks in its own row, for example B2:E2.","grid":{"rows":5,"cols":8},"starter":{"A1":"Store","B1":"Week 1 (K)","C1":"Week 2 (K)","D1":"Week 3 (K)","E1":"Week 4 (K)","F1":"Average (K)","G1":"Best week (K)","H1":"Weakest week (K)","A2":"Nairobi","B2":"420","C2":"385","D2":"450","E2":"395","A3":"Mombasa","B3":"310","C3":"295","D3":"340","E3":"275","A4":"Kisumu","B4":"180","C4":"210","D4":"165","E4":"195","A5":"Eldoret","B5":"240","C5":"260","D5":"255","E5":"225"},"editableCells":["F2","G2","H2","F3","G3","H3","F4","G4","H4","F5","G5","H5"],"allowedFunctions":["AVERAGE","MAX","MIN"],"hints":["A range like B2:E2 means every cell from B2 to E2. Put it inside the function: =AVERAGE(B2:E2).","MAX returns the largest number in the range and MIN returns the smallest: =MAX(B2:E2) and =MIN(B2:E2).","Write the formulas for row 2, then change the row number for each of the other stores (row 3 uses B3:E3, and so on)."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('4e2cde94-010e-5dec-a2c2-da00e668b7cb', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'sum-relative-refs', 'Quarter totals with SUM', '{"schemaVersion":1,"id":"sum-relative-refs","version":1,"title":"Quarter totals with SUM","objective":"Total a column with SUM and reuse the same formula pattern for the next column (relative references).","instructions":"In B5, total North''s sales for January to March. Then total South''s sales in C5 with the same pattern, shifted one column.","grid":{"rows":5,"cols":3},"starter":{"A1":"Month","B1":"North (K)","C1":"South (K)","A2":"Jan","B2":"120","C2":"80","A3":"Feb","B3":"95","C3":"110","A4":"Mar","B4":"143","C4":"97","A5":"Total"},"editableCells":["B5","C5"],"allowedFunctions":["SUM"],"hints":["A formula starts with =. SUM adds every number in a range.","A range uses a colon: B2:B4 means B2 through B4.","Relative references shift with the formula: if B5 refers to B2, the same pattern in C5 refers to C2."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('d622de0e-eded-50b2-b38e-2704fe64c669', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'sumif-region-totals', 'Sales totals by region', '{"schemaVersion":1,"id":"sumif-region-totals","version":1,"title":"Sales totals by region","objective":"Total sales for one region from a sales list with SUMIF and a criteria cell, then check the overall total.","instructions":"The sales list is in A1:C11. In F2:F4, use SUMIF to total the Sales (K) for the region named in E2:E4. Fix both ranges with $ signs and point the criteria at the region cell (E2), so the same formula works on every row. In F5, add the three region totals with SUM.","grid":{"rows":11,"cols":6},"starter":{"A1":"Store","B1":"Region","C1":"Sales (K)","E1":"Region","F1":"Sales (K)","E2":"Nairobi","E3":"Mombasa","E4":"Kisumu","E5":"All regions","A2":"Westlands","B2":"Nairobi","C2":"120","A3":"Nyali","B3":"Mombasa","C3":"85","A4":"Kondele","B4":"Kisumu","C4":"64","A5":"Karen","B5":"Nairobi","C5":"150","A6":"Bamburi","B6":"Mombasa","C6":"92","A7":"Eastleigh","B7":"Nairobi","C7":"98","A8":"Milimani","B8":"Kisumu","C8":"71","A9":"Likoni","B9":"mombasa","C9":"110","A10":"Kibuye","B10":"Kisumu","C10":"58","A11":"Kilimani","B11":"Nairobi","C11":"135"},"editableCells":["F2","F3","F4","F5"],"allowedFunctions":["SUMIF","SUM"],"hints":["SUMIF has three parts: =SUMIF(where to look, what to match, what to add up).","Look in the Region column (B2:B11), match the region in E2, and add the Sales column (C2:C11). Add $ signs so those two ranges stay fixed when you copy the formula down.","For F5, use =SUM(F2:F4) to add the three totals. The region names may be in lower case in the list; SUMIF ignores case."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('9d84c1b6-1390-5f5d-8c29-7052bc51fc68', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'sumif-target-thresholds', 'Sales at or above target', '{"schemaVersion":1,"id":"sumif-target-thresholds","version":1,"title":"Sales at or above target","objective":"Use SUMIF with comparison criteria, a target stored in a cell and a separate sum range.","instructions":"The line list is in A1:D11 and the target (K) is in H2. In F2, total the Sales (K) of lines at or above the target, using \">=\"&H2. In F3, total the Sales (K) of lines below 60. In F4, add up the Pairs sold (column D) on the lines whose Sales are at or above the target. In F5, divide F2 by the total of all sales (use SUM) to get the share as a decimal (for example 0.5, not 50%). Use $ signs on the ranges.","grid":{"rows":11,"cols":8},"starter":{"A1":"Line","B1":"Store","C1":"Sales (K)","D1":"Pairs sold","E1":"Question","F1":"Answer","E2":"Sales on lines at or above target (K)","E3":"Sales on lines below 60K","E4":"Pairs sold on lines at or above target","E5":"Share of sales from lines at or above target","H1":"Target (K)","H2":"100","A2":"1","B2":"Westlands","C2":"120","D2":"48","A3":"2","B3":"Nyali","C3":"85","D3":"34","A4":"3","B4":"Kondele","C4":"64","D4":"26","A5":"4","B5":"Karen","C5":"150","D5":"60","A6":"5","B6":"Bamburi","C6":"92","D6":"37","A7":"6","B7":"Eastleigh","C7":"98","D7":"39","A8":"7","B8":"Milimani","C8":"71","D8":"28","A9":"8","B9":"Likoni","C9":"110","D9":"44","A10":"9","B10":"Kibuye","C10":"58","D10":"23","A11":"10","B11":"Kilimani","C11":"135","D11":"54"},"editableCells":["F2","F3","F4","F5"],"allowedFunctions":["SUMIF","SUM"],"hints":["With no third argument, SUMIF adds the cells it tests: =SUMIF($C$2:$C$11, criteria).","For F2 the criteria is \">=\"&$H$2. For F3 it is \"<60\". For F4 test column C but add column D: =SUMIF($C$2:$C$11,\">=\"&$H$2,$D$2:$D$11).","For F5, divide the F2 result by the whole sales column: =F2/SUM($C$2:$C$11)."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('c44f2427-31fa-5bdd-b3d9-33fd0ecd75c1', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'sumifs-region-category', 'Sales by region and category', '{"schemaVersion":1,"id":"sumifs-region-category","version":1,"title":"Sales by region and category","objective":"Total sales that match both a region and a category with SUMIFS and criteria cells.","instructions":"The sales list is in A1:D13. In G2:G5, use SUMIFS to total the Sales (K) (column D) for the Region in column E and the Category in column F on the same row. Fix the three list ranges with $ signs and point the criteria at the cells in E and F, so one formula works on every row. One combination has no sales: that is fine, show whatever SUMIFS returns.","grid":{"rows":13,"cols":7},"starter":{"A1":"Line","B1":"Region","C1":"Category","D1":"Sales (K)","E1":"Region","F1":"Category","G1":"Sales (K)","E2":"Nairobi","F2":"Sneakers","E3":"Mombasa","F3":"Sandals","E4":"Kisumu","F4":"School","E5":"Kisumu","F5":"Sandals","A2":"1","B2":"Nairobi","C2":"Sneakers","D2":"120","A3":"2","B3":"Nairobi","C3":"Sandals","D3":"45","A4":"3","B4":"Mombasa","C4":"Sandals","D4":"70","A5":"4","B5":"Kisumu","C5":"School","D5":"40","A6":"5","B6":"Nairobi","C6":"Sneakers","D6":"95","A7":"6","B7":"Mombasa","C7":"Sneakers","D7":"60","A8":"7","B8":"Mombasa","C8":"sandals","D8":"55","A9":"8","B9":"Nairobi","C9":"School","D9":"80","A10":"9","B10":"Kisumu","C10":"Sneakers","D10":"35","A11":"10","B11":"Kisumu","C11":"School","D11":"52","A12":"11","B12":"Mombasa","C12":"School","D12":"38","A13":"12","B13":"Nairobi","C13":"sneakers","D13":"30"},"editableCells":["G2","G3","G4","G5"],"allowedFunctions":["SUMIFS"],"hints":["SUMIFS starts with the numbers to add: =SUMIFS(what to add, where to look 1, match 1, where to look 2, match 2).","What to add is $D$2:$D$13. The first condition looks in Region ($B$2:$B$13) for E2; the second looks in Category ($C$2:$C$13) for F2.","Copy the same formula down to G5. The list uses lower case in a couple of places; matching ignores case."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('bfd97a32-b002-5237-9b43-ab1979c531fe', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'summary-table-sumif-check', 'Category summary with a cross-check', '{"schemaVersion":1,"id":"summary-table-sumif-check","version":1,"title":"Category summary with a cross-check","objective":"Fill a summary table with one copied SUMIF formula, total it and show a check message that compares the table total with the list total.","instructions":"The sales list is in A1:C13. In F2:F5, use SUMIF to total the Sales (K) for the category in E2:E5, with $ signs on the two list ranges so the same formula can be copied down. In F6, add F2:F5 with SUM. In F7, use IF to compare F6 with the total of the whole sales list (use SUM on C2:C13): show the text \"OK\" when they are equal and the text \"Check categories\" when they are not.","grid":{"rows":13,"cols":6},"starter":{"A1":"Line","B1":"Category","C1":"Sales (K)","E1":"Category","F1":"Sales (K)","E2":"Sneakers","E3":"Sandals","E4":"School","E5":"Boots","E6":"Total of table","E7":"Check against list","A2":"1","B2":"Sneakers","C2":"120","A3":"2","B3":"Sandals","C3":"45","A4":"3","B4":"School","C4":"80","A5":"4","B5":"Boots","C5":"150","A6":"5","B6":"Sneakers","C6":"95","A7":"6","B7":"sandals","C7":"70","A8":"7","B8":"School","C8":"60","A9":"8","B9":"Boots","C9":"110","A10":"9","B10":"Sneakers","C10":"85","A11":"10","B11":"Sandals","C11":"55","A12":"11","B12":"School","C12":"90","A13":"12","B13":"Boots","C13":"125"},"editableCells":["F2","F3","F4","F5","F6","F7"],"allowedFunctions":["SUMIF","SUM","IF"],"hints":["In F2 look in the Category column ($B$2:$B$13), match E2, and add the Sales column ($C$2:$C$13). Copy it down to F5.","F6 is =SUM(F2:F5). For the check you need the total of the original list: SUM($C$2:$C$13).","F7 has the pattern =IF(table total = list total, \"OK\", \"Check categories\"). Use F6 for the table total and put the texts in double quotes."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('e5b2c79e-f124-5f30-a249-6ddcdaf51b9c', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'trim-before-match', 'Stray spaces and TRIM', '{"schemaVersion":1,"id":"trim-before-match","version":1,"title":"Stray spaces and TRIM","objective":"Use TRIM to remove leading, trailing and doubled spaces, then look up each region''s sales target.","instructions":"Region names in column A were copied from different files and some have extra spaces. Column D shows how many characters were typed, and column E shows what a lookup finds without cleaning. In B2:B7, clean each region name with TRIM. In C2:C7, look up the clean name in column B in the target list in G1:H7 with XLOOKUP and show the text \"Not found\" when there is no match. Fix the target list with $ signs.","grid":{"rows":7,"cols":8},"starter":{"A1":"Region (as typed)","B1":"Clean region","C1":"Target (K)","D1":"Characters typed","E1":"Lookup without TRIM","G1":"Region","H1":"Target (K)","A2":"Nairobi ","D2":"=LEN(A2)","E2":"=XLOOKUP(A2,$G$2:$G$7,$H$2:$H$7,\"Not found\")","A3":" Mombasa","D3":"=LEN(A3)","E3":"=XLOOKUP(A3,$G$2:$G$7,$H$2:$H$7,\"Not found\")","A4":"Kisumu","D4":"=LEN(A4)","E4":"=XLOOKUP(A4,$G$2:$G$7,$H$2:$H$7,\"Not found\")","A5":"Nakuru  ","D5":"=LEN(A5)","E5":"=XLOOKUP(A5,$G$2:$G$7,$H$2:$H$7,\"Not found\")","A6":"Nairobi  CBD","D6":"=LEN(A6)","E6":"=XLOOKUP(A6,$G$2:$G$7,$H$2:$H$7,\"Not found\")","A7":"Eldoret","D7":"=LEN(A7)","E7":"=XLOOKUP(A7,$G$2:$G$7,$H$2:$H$7,\"Not found\")","G2":"Nairobi","H2":"1800","G3":"Mombasa","H3":"950","G4":"Kisumu","H4":"620","G5":"Nakuru","H5":"540","G6":"Eldoret","H6":"480","G7":"Nairobi CBD","H7":"760"},"editableCells":["B2","B3","B4","B5","B6","B7","C2","C3","C4","C5","C6","C7"],"allowedFunctions":["TRIM","XLOOKUP","LEN"],"hints":["TRIM(text) removes spaces at the start and the end of the text, and reduces any run of spaces inside the text to a single space. =TRIM(A2) cleans the name in A2.","Look up the cleaned name in column B, not the raw name in column A: =XLOOKUP(B2,$G$2:$G$7,$H$2:$H$7,\"Not found\").","Compare column E with column C. A lookup on the raw text fails because \"Nairobi \" (with a space) is not the same text as \"Nairobi\"."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('057dadda-8674-5cc6-b3d4-f66faf28394e', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'two-step-region-target', 'Store to region to target', '{"schemaVersion":1,"id":"two-step-region-target","version":1,"title":"Store to region to target","objective":"Use a helper column to find each store''s region, then look up that region''s target.","instructions":"For each store in A2:A7: in B2:B7 use XLOOKUP to find the store in the store list G1:H9 and return its region. In C2:C7 use a second XLOOKUP that uses the region in column B as the key to find the target in the region target table J1:K6. In E2:E7 work out store sales (column D) minus the region target (column C). Fix all table ranges with $ signs.","grid":{"rows":9,"cols":11},"starter":{"A1":"Store","B1":"Region","C1":"Region target (K)","D1":"Store sales (K)","E1":"Sales minus target (K)","A2":"Westlands","D2":"3150","A3":"Nyali","D3":"2380","A4":"Kondele","D4":"1925","A5":"Eldoret Town","D5":"1380","A6":"Thika Road","D6":"2860","A7":"nakuru town","D7":"1710","G1":"Store","H1":"Region","G2":"Westlands","H2":"Nairobi","G3":"Nyali","H3":"Mombasa","G4":"Milimani","H4":"Kisumu","G5":"Nakuru Town","H5":"Nakuru","G6":"Eldoret Town","H6":"Eldoret","G7":"Thika Road","H7":"Nairobi","G8":"Bamburi","H8":"Mombasa","G9":"Kondele","H9":"Kisumu","J1":"Region","K1":"Target (K)","J2":"Nairobi","K2":"3000","J3":"Mombasa","K3":"2500","J4":"Kisumu","K4":"1800","J5":"Nakuru","K5":"1600","J6":"Eldoret","K6":"1400"},"editableCells":["B2","B3","B4","B5","B6","B7","C2","C3","C4","C5","C6","C7","E2","E3","E4","E5","E6","E7"],"allowedFunctions":["XLOOKUP"],"hints":["There are two lookups. The first finds the region from the store name, the second finds the target from the region.","For B2: find A2 in the store column G2:G9 and return the region from H2:H9, with $ signs on both ranges.","For C2: the key is the region in B2. Look it up in the region column J2:J6 and return the target from K2:K6.","For E2 use D2-C2. The second lookup depends on the first, so if column B shows an error, fix it first."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('4db78cb0-5123-5347-9205-02e9248466be', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'vat-and-discount-prices', 'VAT and sale prices from a rate in an input cell', '{"schemaVersion":1,"id":"vat-and-discount-prices","version":1,"title":"VAT and sale prices from a rate in an input cell","objective":"Calculate a VAT amount, a price including VAT and a discounted price using rates held in input cells.","instructions":"B1 holds an example VAT rate and B2 holds a sale discount (0.16 means 16%). Each item''s price in column B excludes VAT. In C5:C8, work out the VAT amount: the price times the VAT rate. In D5:D8, work out the price including VAT: the price plus the VAT amount. In E5:E8, work out the sale price: the price including VAT, less the discount. In C9, add up the four VAT amounts with SUM. Refer to the rate and the discount with $B$1 and $B$2, never by typing the numbers.","grid":{"rows":9,"cols":5},"starter":{"A1":"VAT rate (example)","B1":"0.16","A2":"Discount","B2":"0.15","A4":"Item","B4":"Price excl. VAT (KES)","C4":"VAT amount (KES)","D4":"Price incl. VAT (KES)","E4":"Sale price (KES)","A9":"Total VAT","A5":"Sneakers","B5":"2500","A6":"Sandals","B6":"1200","A7":"Boots","B7":"4000","A8":"School shoes","B8":"1800"},"editableCells":["C5","D5","E5","C6","D6","E6","C7","D7","E7","C8","D8","E8","C9"],"allowedFunctions":["SUM"],"hints":["VAT amount = price x rate. Lock the rate with dollar signs so it can be copied down: =B5*$B$1.","Price including VAT is the price plus the VAT: =B5+C5. For the sale price, multiply by what is left after the discount: =D5*(1-$B$2).","In C9 use =SUM(C5:C8). If the sale price looks too high, check the brackets: 1-$B$2 must be worked out before multiplying."],"namedRanges":{},"timeoutMs":500}'::jsonb),
  ('79f8240c-dcab-5f51-8130-94b498e8a4de', 'e1066c4a-7a8f-5990-bbf6-8f368248d03e', 'excel', 'xlookup-price-list', 'Unit prices with XLOOKUP', '{"schemaVersion":1,"id":"xlookup-price-list","version":1,"title":"Unit prices with XLOOKUP","objective":"Look up a value from a product table with an exact-match XLOOKUP, fixed table references and a not-found fallback.","instructions":"In C2:C5, look up each order line''s unit price (KES) from the price list in E1:G6 with XLOOKUP. Fix the price list with $ signs so the formula can be reused on every row. If a code is not on the price list, show the text \"Not listed\" instead of #N/A.","grid":{"rows":6,"cols":7},"starter":{"A1":"Line","B1":"Product code","C1":"Unit price","A2":"1","B2":"SS-210","A3":"2","B3":"SN-450","A4":"3","B4":"sd-120","A5":"4","B5":"GB-610","E1":"Code","F1":"Product","G1":"Price (KES)","E2":"SS-210","F2":"School shoe","G2":"2499","E3":"SN-450","F3":"Canvas sneaker","G3":"1999","E4":"SD-120","F4":"Ladies sandal","G4":"899","E5":"BT-330","F5":"Ankle boot","G5":"4599","E6":"SL-075","F6":"Slipper","G6":"499"},"editableCells":["C2","C3","C4","C5"],"allowedFunctions":["XLOOKUP"],"hints":["XLOOKUP has three parts plus an optional fourth: =XLOOKUP(what to find, where to look, what to return, [if not found]).","Look for the code in B2 inside the Code column of the price list, and return the matching cell from the Price column.","Add $ signs to the price list ranges (for example $E$2:$E$6) so they stay fixed on every row, while B2 becomes B3, B4 and B5.","Text matching ignores upper and lower case, so \"sd-120\" finds \"SD-120\". The fourth argument, in double quotes, replaces #N/A."],"namedRanges":{},"timeoutMs":500}'::jsonb)
insert into app_private.exercise_keys (exercise_id, expected, hidden_tests, updated_at) values
  ('0660b26f-d024-5d1e-a03e-9e9b10ffebe5', '{"schemaVersion":1,"derivedFrom":"public datasets","items":[{"id":"practice-mean-store-a","type":"numeric","expected":162.5,"tolerance":{"kind":"absolute","value":0.05}},{"id":"practice-median-store-a","type":"numeric","expected":147,"tolerance":{"kind":"absolute","value":0.05}}]}'::jsonb, '[]'::jsonb, '2026-11-11T00:00:00Z'::timestamptz),
  ('f8d2286b-18ae-507c-add9-c97cf4777735', '{"schemaVersion":1,"exerciseId":"article-prefix-left","exerciseVersion":1,"expected":[{"id":"c-b2","cell":"B2","value":"SN","label":"Category prefix of article 1"},{"id":"c-b3","cell":"B3","value":"SD","label":"Category prefix of article 2"},{"id":"c-b4","cell":"B4","value":"bt","label":"Category prefix of article 3"},{"id":"c-b5","cell":"B5","value":"SS","label":"Category prefix of article 4"},{"id":"c-b6","cell":"B6","value":"XX","label":"Category prefix of article 5"},{"id":"c-b7","cell":"B7","value":"SL","label":"Category prefix of article 6"},{"id":"c-c2","cell":"C2","value":"Sneaker","label":"Category name of article 1"},{"id":"c-c3","cell":"C3","value":"Sandal","label":"Category name of article 2"},{"id":"c-c4","cell":"C4","value":"Boot","label":"Category name of article 3"},{"id":"c-c5","cell":"C5","value":"School shoe","label":"Category name of article 4"},{"id":"c-c6","cell":"C6","value":"Unknown","label":"Category name of article 5"},{"id":"c-c7","cell":"C7","value":"Slipper","label":"Category name of article 6"},{"id":"c-d2","cell":"D2","value":"SN-450","label":"Style code of article 1"},{"id":"c-d3","cell":"D3","value":"SD-120","label":"Style code of article 2"},{"id":"c-d4","cell":"D4","value":"bt-330","label":"Style code of article 3"},{"id":"c-d5","cell":"D5","value":"SS-210","label":"Style code of article 4"},{"id":"c-d6","cell":"D6","value":"XX-001","label":"Style code of article 5"},{"id":"c-d7","cell":"D7","value":"SL-075","label":"Style code of article 6"}],"requireFormula":["B2","B3","B4","B5","B6","B7","C2","C3","C4","C5","C6","C7","D2","D3","D4","D5","D6","D7"],"requireFunctions":{"B2":["LEFT"],"C2":["XLOOKUP"],"D2":["LEFT"],"B3":["LEFT"],"C3":["XLOOKUP"],"D3":["LEFT"],"B4":["LEFT"],"C4":["XLOOKUP"],"D4":["LEFT"],"B5":["LEFT"],"C5":["XLOOKUP"],"D5":["LEFT"],"B6":["LEFT"],"C6":["XLOOKUP"],"D6":["LEFT"],"B7":["LEFT"],"C7":["XLOOKUP"],"D7":["LEFT"]},"passThreshold":100}'::jsonb, '[{"id":"left-category-