insert into public.assessment_items (id, assessment_id, position, kind, prompt, options, points) values
  ('22a2de43-6b90-5df2-bfbc-91b706cb839f', '8cab4d19-5fd0-5a11-a875-ef743b5b7581', 1, 'numeric', '{"itemId":"a1-mean-store-b","text":"What is the mean number of pairs Store B sold per week? Round to 1 decimal place.","datasetId":"store-b-weekly-pairs","answerHint":"1 decimal place","dataset":{"id":"store-b-weekly-pairs","title":"Store B: pairs sold per week, weeks 1 to 9","unit":"pairs","labels":["Wk 1","Wk 2","Wk 3","Wk 4","Wk 5","Wk 6","Wk 7","Wk 8","Wk 9"],"values":[86,94,78,91,240,88,83,97,90],"adjustable":{"index":4,"min":50,"max":300,"step":1,"label":"Week 5 (bulk school order)"},"spread":"sample","decimals":1}}'::jsonb, null, 1),
  ('dae087ee-3729-540f-94fa-eef438ba4302', '8cab4d19-5fd0-5a11-a875-ef743b5b7581', 2, 'numeric', '{"itemId":"a2-median-store-b","text":"What is the median number of pairs Store B sold per week?","datasetId":"store-b-weekly-pairs","answerHint":"Whole number","dataset":{"id":"store-b-weekly-pairs","title":"Store B: pairs sold per week, weeks 1 to 9","unit":"pairs","labels":["Wk 1","Wk 2","Wk 3","Wk 4","Wk 5","Wk 6","Wk 7","Wk 8","Wk 9"],"values":[86,94,78,91,240,88,83,97,90],"adjustable":{"index":4,"min":50,"max":300,"step":1,"label":"Week 5 (bulk school order)"},"spread":"sample","decimals":1}}'::jsonb, null, 1),
  ('cbc939f4-aa2d-5dbe-80a4-f88735ec9adc', '8cab4d19-5fd0-5a11-a875-ef743b5b7581', 3, 'numeric', '{"itemId":"a3-sd-store-b","text":"What is the sample standard deviation (Excel STDEV.S) of Store B''s weekly pairs? Round to 2 decimal places.","datasetId":"store-b-weekly-pairs","answerHint":"2 decimal places","dataset":{"id":"store-b-weekly-pairs","title":"Store B: pairs sold per week, weeks 1 to 9","unit":"pairs","labels":["Wk 1","Wk 2","Wk 3","Wk 4","Wk 5","Wk 6","Wk 7","Wk 8","Wk 9"],"values":[86,94,78,91,240,88,83,97,90],"adjustable":{"index":4,"min":50,"max":300,"step":1,"label":"Week 5 (bulk school order)"},"spread":"sample","decimals":1}}'::jsonb, null, 1),
  ('91183e1f-875c-5cc5-8684-687bf35c5913', '8cab4d19-5fd0-5a11-a875-ef743b5b7581', 4, 'single_choice', '{"itemId":"a4-typical-week","text":"Store B''s week 5 includes a one-off bulk order. Which single figure best describes a typical week for replenishment planning?"}'::jsonb, '[{"id":"mean","label":"The mean"},{"id":"median","label":"The median"},{"id":"range","label":"The range"},{"id":"sd","label":"The standard deviation"}]'::jsonb, 1),
  ('cf77dc07-214e-562c-aaf0-f011e12f0eeb', 'd18d03c1-8e66-5ed5-93c1-65077dec8cbe', 1, 'single_choice', '{"itemId":"i1-and-result","text":"What does =AND(5>3,2>4) return?"}'::jsonb, '[{"id":"choice-a","label":"TRUE"},{"id":"choice-b","label":"FALSE"},{"id":"five","label":"5"},{"id":"error","label":"#VALUE!"}]'::jsonb, 1),
  ('4b366f06-3b33-5ccb-8624-d25589117410', 'd18d03c1-8e66-5ed5-93c1-65077dec8cbe', 2, 'numeric', '{"itemId":"i2-count-reorders","text":"The rule is: reorder when stock is below the reorder point AND the status is not Discontinued. Line A has stock 12, reorder point 20, Active. Line B has stock 8, reorder point 8, Active. Line C has stock 3, reorder point 10, Discontinued. How many lines need a reorder?","answerHint":"A whole number"}'::jsonb, null, 1),
  ('8a80903c-2c0c-5a9e-9038-8ae3388596c2', 'd18d03c1-8e66-5ed5-93c1-65077dec8cbe', 3, 'single_choice', '{"itemId":"i3-star-formula","text":"Which formula shows Star only when margin in E2 is above the target in B8 and sell-through in F2 is above the target in B9?"}'::jsonb, '[{"id":"and-ok","label":"=IF(AND(E2>$B$8,F2>$B$9),\"Star\",\"Review\")"},{"id":"and-bare","label":"=IF(AND(E2>$B$8,F2),\"Star\",\"Review\")"},{"id":"and-word","label":"=IF(E2>$B$8 AND F2>$B$9,\"Star\",\"Review\")"},{"id":"one-test","label":"=IF(E2>$B$8,\"Star\",\"Review\")"}]'::jsonb, 1),
  ('49a637e5-657b-522b-9d0d-0114f60b375e', 'd18d03c1-8e66-5ed5-93c1-65077dec8cbe', 4, 'single_choice', '{"itemId":"i4-boundary","text":"A line has a margin of exactly 40% and the margin target in B8 is 40%. Its sell-through beats the target. What does =IF(AND(E2>$B$8,F2>$B$9),\"Star\",\"Review\") show?"}'::jsonb, '[{"id":"review","label":"Review"},{"id":"star","label":"Star"},{"id":"choice-c","label":"TRUE"},{"id":"error","label":"#NAME?"}]'::jsonb, 1),
  ('c6ec8139-71cb-54ed-8a71-5af21c303190', 'f1ae15e2-5b30-53fd-aa1b-7663043b87f8', 1, 'numeric', '{"itemId":"l1-nairobi-average","text":"What does =AVERAGEIF(B2:B7,\"Nairobi\",C2:C7) return, in K?","answerHint":"To 1 decimal place, in K"}'::jsonb, null, 1),
  ('c52714b1-660b-56f7-ac62-ef323815664a', 'f1ae15e2-5b30-53fd-aa1b-7663043b87f8', 2, 'numeric', '{"itemId":"l2-mombasa-average","text":"What does =AVERAGEIF(B2:B7,\"Mombasa\",C2:C7) return, in K?","answerHint":"To 1 decimal place, in K"}'::jsonb, null, 1),
  ('f1dd5d4c-163a-5718-b385-c75551240212', 'f1ae15e2-5b30-53fd-aa1b-7663043b87f8', 3, 'single_choice', '{"itemId":"l3-no-match","text":"What does =AVERAGEIF(B2:B7,\"Eldoret\",C2:C7) show when there is no Eldoret store in the list?"}'::jsonb, '[{"id":"zero","label":"0"},{"id":"div0","label":"#DIV/0!"},{"id":"na","label":"#N/A"},{"id":"all","label":"The average of all stores"}]'::jsonb, 1),
  ('4497588e-dddb-576b-b722-0431e82d615f', 'f1ae15e2-5b30-53fd-aa1b-7663043b87f8', 4, 'single_choice', '{"itemId":"l4-same-as","text":"Which formula gives the same answer as =AVERAGEIF(B2:B7,\"Nairobi\",C2:C7)?"}'::jsonb, '[{"id":"sumif-countif","label":"SUMIF(B2:B7,\"Nairobi\",C2:C7)/COUNTIF(B2:B7,\"Nairobi\")"},{"id":"sumif-count","label":"SUMIF(B2:B7,\"Nairobi\",C2:C7)/COUNT(C2:C7)"},{"id":"average-all","label":"AVERAGE(C2:C7)"},{"id":"countif-sales","label":"SUMIF(B2:B7,\"Nairobi\",C2:C7)/COUNTIF(C2:C7,\"Nairobi\")"}]'::jsonb, 1),
  ('76ff5903-4b7e-591a-a4fc-7e0185c1766a', 'a92ec8df-aaeb-502c-8cfa-bdb39b3d1c3d', 1, 'numeric', '{"itemId":"i1-average","text":"A store''s four weekly sales, in K, are 110, 150, 95 and 145. What does =AVERAGE of those four cells return, in K?","answerHint":"Whole number, in K"}'::jsonb, null, 1),
  ('e84e34f8-bdab-540f-8f6f-fefb6d567d4a', 'a92ec8df-aaeb-502c-8cfa-bdb39b3d1c3d', 2, 'single_choice', '{"itemId":"i2-empty-cell","text":"Weekly sales, in K, are 200, (an empty cell because the store was closed), 100 and 300. What does AVERAGE over the four cells return?"}'::jsonb, '[{"id":"two-hundred","label":"200"},{"id":"one-fifty","label":"150"},{"id":"div0","label":"#DIV/0!"},{"id":"six-hundred","label":"600"}]'::jsonb, 1),
  ('8ece72af-e1c5-57c8-9cf4-ac91a8ccfec1', 'a92ec8df-aaeb-502c-8cfa-bdb39b3d1c3d', 3, 'numeric', '{"itemId":"i3-spread","text":"A store''s four weekly sales, in K, are 230, 185, 310 and 265. What does =MAX(B2:E2)-MIN(B2:E2) return, in K? This is the gap between the best and the weakest week.","answerHint":"Whole number, in K"}'::jsonb, null, 1),
  ('b87b610e-3e99-5886-b1de-c828589b3b60', 'a92ec8df-aaeb-502c-8cfa-bdb39b3d1c3d', 4, 'single_choice', '{"itemId":"i4-extremes","text":"Store sales over four weeks are 100, 100, 100 and 500 (K). The average is 200. Which statement is correct?"}'::jsonb, '[{"id":"pulled-up","label":"One big week pulls the average up, so MIN and MAX are useful to show how uneven the weeks were"},{"id":"typical","label":"200 is a typical week, so MIN and MAX add nothing"},{"id":"choice-c","label":"AVERAGE is wrong here, because it should be 100"},{"id":"median","label":"AVERAGE ignores the largest number, so the 500 has no effect"}]'::jsonb, 1),
  ('9e17f2a9-5a11-5635-ba20-a8d343e210cc', 'd0a32b36-3ff9-5410-8323-974193ef41d8', 1, 'numeric', '{"itemId":"i1-variance","text":"A store had a budget of 500K and an actual of 455K. What is the variance (actual minus budget), in K? Include the minus sign if it is negative.","answerHint":"Number in K, with a minus sign if below budget"}'::jsonb, null, 1),
  ('cb6504a6-c38b-513c-87ad-7ed4304e3a67', 'd0a32b36-3ff9-5410-8323-974193ef41d8', 2, 'numeric', '{"itemId":"i2-variance-pct","text":"For the same store (budget 500K, actual 455K), what is the variance %, to 1 decimal place? Include the minus sign.","answerHint":"Number, 1 decimal place, with a minus sign if below budget"}'::jsonb, null, 1),
  ('aee57100-9947-501a-a9e2-22ac1b2032f4', 'd0a32b36-3ff9-5410-8323-974193ef41d8', 3, 'single_choice', '{"itemId":"i3-why-abs","text":"Why does the flag formula use ABS(E2) in =IF(ABS(E2)>$I$2,\"Miss\",\"On track\")?"}'::jsonb, '[{"id":"both-ways","label":"So that a store far below budget (a negative %) is flagged just like one far above it"},{"id":"round","label":"To round the variance to 1 decimal place"},{"id":"positive-only","label":"Because variance % can never be negative"},{"id":"count","label":"To count the stores that missed"}]'::jsonb, 1),
  ('bd514ed6-9ccf-5527-9ceb-ec555c8dfb38', 'd0a32b36-3ff9-5410-8323-974193ef41d8', 4, 'numeric', '{"itemId":"i4-countif","text":"The flags in F2:F6 read Miss, On track, Miss, Miss, On track. What does =COUNTIF(F2:F6,\"Miss\") return?","answerHint":"Whole number"}'::jsonb, null, 1),
  ('8f7bdec7-792e-579a-a3e1-372f4bc71cf8', 'ba429b1c-97f9-578f-9b3f-cf44d04cac9d', 1, 'single_choice', '{"itemId":"l1-upper-result","text":"What does =UPPER(\"Nbo-01\") return?"}'::jsonb, '[{"id":"caps","label":"NBO-01"},{"id":"lower","label":"nbo-01"},{"id":"same","label":"Nbo-01"},{"id":"first","label":"N"}]'::jsonb, 1),
  ('e979a333-2477-5b07-8f0e-3958a85b7e9b', 'ba429b1c-97f9-578f-9b3f-cf44d04cac9d', 2, 'single_choice', '{"itemId":"l2-compare-case","text":"What does =(\"NBO-01\"=\"nbo-01\") return in Excel?"}'::jsonb, '[{"id":"choice-a","label":"TRUE"},{"id":"choice-b","label":"FALSE"},{"id":"error","label":"#VALUE!"},{"id":"na","label":"#N/A"}]'::jsonb, 1),
  ('7f11fc6e-c158-5daa-af96-96d5322e9d14', 'ba429b1c-97f9-578f-9b3f-cf44d04cac9d', 3, 'numeric', '{"itemId":"l3-upper-length","text":"What does =LEN(UPPER(\"Eldoret\")) return?","answerHint":"Whole number"}'::jsonb, null, 1),
  ('551876b6-0f8d-5d1b-94b3-55c4b367f037', 'ba429b1c-97f9-578f-9b3f-cf44d04cac9d', 4, 'single_choice', '{"itemId":"l4-why-standard","text":"Excel ignores case in comparisons and lookups. Why should you still standardise the case of codes?"}'::jsonb, '[{"id":"other-tools","label":"Other tools, such as Power Query merges, can treat NBO-01 and nbo-01 as different, and consistent codes read better"},{"id":"formulas","label":"Because Excel formulas cannot compare lower-case text"},{"id":"shorter","label":"Because UPPER makes the codes shorter"},{"id":"xlookup","label":"Because XLOOKUP only works on capitals"}]'::jsonb, 1),
  ('23b7182c-d184-5455-8cd2-2b0a75fa9e90', '0de39a72-f268-5bff-a2c9-3b15380306e9', 1, 'single_choice', '{"itemId":"l1-order-of-work","text":"In =XLOOKUP(UPPER(TRIM(A2)),...), which function does Excel work out first?"}'::jsonb, '[{"id":"trim","label":"TRIM, because it is the innermost"},{"id":"upper","label":"UPPER, because it is written first"},{"id":"xlookup","label":"XLOOKUP, because it is the outer function"},{"id":"together","label":"All three at the same time"}]'::jsonb, 1),
  ('0bd5e5dd-a8ed-5394-821a-a3784d6d3b75', '0de39a72-f268-5bff-a2c9-3b15380306e9', 2, 'numeric', '{"itemId":"l2-price-after-trim","text":"What does =XLOOKUP(UPPER(TRIM(\"  sl-075 \")),$E$2:$E$6,$G$2:$G$6) return, in KES?","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('75f41801-112f-50da-af4e-3660b95b6196', '0de39a72-f268-5bff-a2c9-3b15380306e9', 3, 'single_choice', '{"itemId":"l3-trailing-space","text":"Cell A3 holds SD-120 followed by one space. What does =XLOOKUP(A3,$E$2:$E$6,$G$2:$G$6) return, with no fourth argument and no cleaning?"}'::jsonb, '[{"id":"na","label":"#N/A"},{"id":"price","label":"899, the price of SD-120"},{"id":"zero","label":"0"},{"id":"value","label":"#VALUE!"}]'::jsonb, 1),
  ('47ecfae3-fd45-5d35-81e1-44329a43fa84', '0de39a72-f268-5bff-a2c9-3b15380306e9', 4, 'single_choice', '{"itemId":"l4-upper-role","text":"Which statement about UPPER in this lookup is true?"}'::jsonb, '[{"id":"optional","label":"XLOOKUP ignores case, so UPPER is optional for finding the price, but it gives one standard code for reports and exports"},{"id":"required","label":"UPPER is required, otherwise XLOOKUP cannot find lower-case codes"},{"id":"spaces","label":"UPPER removes the stray spaces"},{"id":"ignore","label":"XLOOKUP ignores spaces, so only UPPER is needed"}]'::jsonb, 1),
  ('659de5c7-7a56-5b70-a2fc-aedc897dbdad', '4db5c40f-3c15-5f9d-b637-6a5d918d2d60', 1, 'numeric', '{"itemId":"i1-count","text":"The range B2:B7 holds 12, 0, n/a, 5, an empty cell and 30. What does =COUNT(B2:B7) return?","answerHint":"A whole number"}'::jsonb, null, 1),
  ('b5f14ef0-cf52-5466-9d67-0874b6bc13d3', '4db5c40f-3c15-5f9d-b637-6a5d918d2d60', 2, 'single_choice', '{"itemId":"i2-zero","text":"A store counted a style and found no pairs left, so it typed 0. Does COUNT include that cell?"}'::jsonb, '[{"id":"choice-a","label":"Yes, because 0 is a number"},{"id":"no","label":"No, because 0 means nothing was entered"},{"id":"only-format","label":"Only if the cell is formatted as a number"},{"id":"error","label":"No, it returns an error"}]'::jsonb, 1),
  ('c62895c8-e87e-53d8-bd8c-06b2e83600da', '4db5c40f-3c15-5f9d-b637-6a5d918d2d60', 3, 'numeric', '{"itemId":"i3-average","text":"The range C2:C7 holds 25, TBC, 40, 0, an empty cell and 15. What does =SUM(C2:C7)/COUNT(C2:C7) return?","answerHint":"Whole number, in pairs"}'::jsonb, null, 1),
  ('8548afba-dce9-59ff-9e33-ea26a0dd9d4d', '4db5c40f-3c15-5f9d-b637-6a5d918d2d60', 4, 'single_choice', '{"itemId":"i4-text-number","text":"One cell in a stock list holds the text ''18 (typed with an apostrophe in front). What does COUNT do with it?"}'::jsonb, '[{"id":"ignores","label":"It ignores it, because the cell holds text even though it looks like a number"},{"id":"counts","label":"It counts it, because the characters are digits"},{"id":"error","label":"It returns #VALUE!"},{"id":"zero","label":"It counts it as 0"}]'::jsonb, 1),
  ('12b14d52-1aa8-5979-8f08-043530ae9e3c', 'f0185db9-a2dc-51e1-b9b9-00a23b5db8d0', 1, 'numeric', '{"itemId":"l1-open-count","text":"What does =COUNTIF(B2:B8,\"Open\") return?","answerHint":"Whole number"}'::jsonb, null, 1),
  ('73e9978c-e430-5b23-9e16-ee4bcec685a6', 'f0185db9-a2dc-51e1-b9b9-00a23b5db8d0', 2, 'numeric', '{"itemId":"l2-not-open","text":"What does =COUNTIF(B2:B8,\"<>Open\") return?","answerHint":"Whole number"}'::jsonb, null, 1),
  ('5bd6ce4e-ee66-53b9-ad43-ba8ca9e31bec', 'f0185db9-a2dc-51e1-b9b9-00a23b5db8d0', 3, 'single_choice', '{"itemId":"l3-no-match","text":"No store in the list has the status \"Relocated\". What does =COUNTIF(B2:B8,\"Relocated\") show?"}'::jsonb, '[{"id":"zero","label":"0"},{"id":"na","label":"#N/A"},{"id":"blank","label":"An empty cell"},{"id":"one","label":"1, because Excel rounds up"}]'::jsonb, 1),
  ('36fd9168-99da-5cf1-be5a-7c7f14b977b0', 'f0185db9-a2dc-51e1-b9b9-00a23b5db8d0', 4, 'single_choice', '{"itemId":"l4-which-function","text":"You want the number of order lines for Nairobi, not their value in KES. Which function fits?"}'::jsonb, '[{"id":"countif","label":"COUNTIF, because you want how many lines"},{"id":"sumif","label":"SUMIF, because it also looks at one column"},{"id":"average","label":"AVERAGE, because it summarises a list"},{"id":"if","label":"IF, because it tests one cell"}]'::jsonb, 1),
  ('e6b66724-4536-5347-93fa-1473020cf5de', 'da8397be-e280-5023-bf39-e066e8dd7280', 1, 'numeric', '{"itemId":"l1-band","text":"What does =COUNTIFS(B2:B8,\">=10\",B2:B8,\"<20\") return?","answerHint":"Whole number"}'::jsonb, null, 1),
  ('f872ed8a-e257-5f92-b60e-a511a4b118b0', 'da8397be-e280-5023-bf39-e066e8dd7280', 2, 'numeric', '{"itemId":"l2-region-and-stock","text":"What does =COUNTIFS(A2:A8,\"Nairobi\",B2:B8,\">=10\") return?","answerHint":"Whole number"}'::jsonb, null, 1),
  ('ca5e3539-26cb-5c7b-829e-130b12290156', 'da8397be-e280-5023-bf39-e066e8dd7280', 3, 'single_choice', '{"itemId":"l3-band-edges","text":"Two bands are written \">=10 and <=20\" and \">=20 and <=30\". What happens to a line with exactly 20 pairs?"}'::jsonb, '[{"id":"both","label":"It is counted in both bands"},{"id":"neither","label":"It is counted in neither band"},{"id":"first","label":"It is counted only in the first band"},{"id":"error","label":"Excel shows an error"}]'::jsonb, 1),
  ('8bd66b9b-da05-53ca-830c-a55d23554328', 'da8397be-e280-5023-bf39-e066e8dd7280', 4, 'single_choice', '{"itemId":"l4-same-column-twice","text":"What does =COUNTIFS(A2:A8,\"Nairobi\",A2:A8,\"Mombasa\") return?"}'::jsonb, '[{"id":"zero","label":"0, because no cell can be both Nairobi and Mombasa"},{"id":"both","label":"The number of Nairobi and Mombasa rows together"},{"id":"na","label":"#N/A"},{"id":"one","label":"1"}]'::jsonb, 1),
  ('f7f9dc54-18f0-5388-b052-938845ee76cd', '5163ae7e-0498-5a23-82ce-9b5ec74d19d0', 1, 'numeric', '{"itemId":"l1-share","text":"What percentage of the six lines are below their reorder point? Give the number to 1 decimal place (for example 33.3).","answerHint":"Percentage to 1 decimal place"}'::jsonb, null, 1),
  ('506ca600-c909-5455-9539-a69545c94732', '5163ae7e-0498-5a23-82ce-9b5ec74d19d0', 2, 'numeric', '{"itemId":"l2-kisumu-value","text":"What does =SUMIFS(D2:D7,E2:E7,\"Yes\",A2:A7,\"Kisumu\") return, in K?","answerHint":"Whole number, in K"}'::jsonb, null, 1),
  ('6cf55205-6f54-5d05-972e-2ab5dd84b695', '5163ae7e-0498-5a23-82ce-9b5ec74d19d0', 3, 'single_choice', '{"itemId":"l3-helper","text":"Why do we add a Yes/No helper column instead of using COUNTIFS directly on the two columns?"}'::jsonb, '[{"id":"row-compare","label":"COUNTIFS compares a column to a fixed value, not one column to another row by row"},{"id":"slow","label":"COUNTIFS is too slow on stock data"},{"id":"text","label":"COUNTIFS cannot read numbers"},{"id":"one-column","label":"COUNTIFS only works on one column"}]'::jsonb, 1),
  ('93c432d6-5e96-50d9-a61a-cb878978de52', '5163ae7e-0498-5a23-82ce-9b5ec74d19d0', 4, 'single_choice', '{"itemId":"l4-boundary","text":"Row 3 has 30 pairs in stock and a reorder point of 30. What does =IF(B3<C3,\"Yes\",\"No\") show for it?"}'::jsonb, '[{"id":"no","label":"No, because 30 is not below 30"},{"id":"choice-b","label":"Yes, because the stock has reached the reorder point"},{"id":"zero","label":"0"},{"id":"error","label":"An error"}]'::jsonb, 1),
  ('9e8ab982-9b49-55c5-a376-aba919c12657', 'c9a0f909-74d5-5946-84b1-12bd597f5a9b', 1, 'numeric', '{"itemId":"g1-grade-c","text":"What discount percentage does =XLOOKUP(\"C\",$H$2:$H$5,$I$2:$I$5,0) give? Answer as a percentage, for example 4 for 4%.","answerHint":"Percentage number"}'::jsonb, null, 1),
  ('864452b3-3afd-5a7b-90fc-83b08e2d6c87', 'c9a0f909-74d5-5946-84b1-12bd597f5a9b', 2, 'single_choice', '{"itemId":"g2-exact-score","text":"A score table lists only the band starts 0, 50, 70 and 85. What does an exact-match XLOOKUP of the score 73 in that list give?"}'::jsonb, '[{"id":"b","label":"The grade for the band 70 to 84"},{"id":"na","label":"#N/A, because 73 is not exactly in the list"},{"id":"c","label":"The grade of the nearest score, 70"},{"id":"zero","label":"0"}]'::jsonb, 1),
  ('36ce779b-f48b-5a7e-a331-6e1be0012198', 'c9a0f909-74d5-5946-84b1-12bd597f5a9b', 3, 'single_choice', '{"itemId":"g3-label-fix","text":"What is the best way to give each customer a discount from a score between 0 and 100 using exact-match XLOOKUP?"}'::jsonb, '[{"id":"type","label":"Use an IF formula to turn each score into a grade label, then look up the grade in the discount table"},{"id":"round","label":"Look up the score directly and hope it matches"},{"id":"bigger","label":"Add every score from 0 to 100 as a number to the discount table by hand"},{"id":"case","label":"Change the score to upper case"}]'::jsonb, 1),
  ('55103e08-e863-5a89-b90a-39b8c10eabe5', 'c9a0f909-74d5-5946-84b1-12bd597f5a9b', 4, 'numeric', '{"itemId":"g4-net","text":"A grade B order is worth 600K. Using the discount table, what is the net order after the discount, in K?","answerHint":"Number in K"}'::jsonb, null, 1),
  ('0aced0cc-3144-5fe5-a0dd-febf3675310e', 'a5b316ea-3ff1-5a4e-85af-86e8f98d5e59', 1, 'numeric', '{"itemId":"i1-growth","text":"A store sold 480K last year and 600K this year. What is its growth, as a percentage? Type 25 for 25%.","answerHint":"A percentage, for example 25 for 25%"}'::jsonb, null, 1),
  ('11994921-660e-50f7-bf67-f2b2fa0f057d', 'a5b316ea-3ff1-5a4e-85af-86e8f98d5e59', 2, 'numeric', '{"itemId":"i2-decline","text":"A store sold 200K last year and 150K this year. What is its change, as a percentage? Type -10 for a 10% fall.","answerHint":"A negative percentage for a fall"}'::jsonb, null, 1),
  ('0fce59c8-2a07-504b-9eed-42185cdfa2d0', 'a5b316ea-3ff1-5a4e-85af-86e8f98d5e59', 3, 'single_choice', '{"itemId":"i3-base","text":"Why does the formula divide by last year and not by this year?"}'::jsonb, '[{"id":"base","label":"Last year is the starting point, so the change is measured as a share of where we started"},{"id":"bigger","label":"Last year is always the larger number"},{"id":"excel","label":"Excel only allows dividing by the first number"},{"id":"same","label":"It makes no difference; either gives the same answer"}]'::jsonb, 1),
  ('84e31cc3-f22d-58bc-a06f-5efa81ff5aff', 'a5b316ea-3ff1-5a4e-85af-86e8f98d5e59', 4, 'single_choice', '{"itemId":"i4-guard","text":"Last year is in B6 and this year in C6. B6 can be 0 for a new store. Which formula shows New for it and growth for other stores?"}'::jsonb, '[{"id":"choice-a","label":"=IF(B6=0,\"New\",(C6-B6)/B6)"},{"id":"swapped","label":"=IF(B6=0,(C6-B6)/B6,\"New\")"},{"id":"wrong-cell","label":"=IF(C6=0,\"New\",(C6-B6)/B6)"},{"id":"no-guard","label":"=(C6-B6)/C6"}]'::jsonb, 1),
  ('acd6e606-9dc1-5d20-97be-4195add712a2', 'a3528aab-a33b-5689-bd81-bc5930b0cf42', 1, 'single_choice', '{"itemId":"i1-boundary","text":"Ankle boots: 30 pairs on hand (B4), reorder point 30 (C4). What does =IF(B4<=C4,\"Reorder\",\"OK\") show?"}'::jsonb, '[{"id":"reorder","label":"Reorder"},{"id":"ok","label":"OK"},{"id":"choice-c","label":"FALSE"},{"id":"error","label":"#VALUE!"}]'::jsonb, 1),
  ('a6f43a05-3b75-5f45-a257-82c77828927e', 'a3528aab-a33b-5689-bd81-bc5930b0cf42', 2, 'single_choice', '{"itemId":"i2-bonus-formula","text":"A store earns a \"Bonus\" when weekly sales in B2 are at least KES 50,000; otherwise the cell stays empty. Which formula is correct?"}'::jsonb, '[{"id":"gt","label":"=IF(B2>50000,\"Bonus\",\"\")"},{"id":"gte","label":"=IF(B2>=50000,\"Bonus\",\"\")"},{"id":"no-quotes","label":"=IF(B2>=50000,Bonus,\"\")"},{"id":"lte","label":"=IF(B2<=50000,\"Bonus\",\"\")"}]'::jsonb, 1),
  ('a7b20674-2e14-51a9-82cb-27e190a25a0d', 'a3528aab-a33b-5689-bd81-bc5930b0cf42', 3, 'numeric', '{"itemId":"i3-commission","text":"A sales associate sold KES 7,200 of shoes (B2). What does =IF(B2>=5000,B2*5%,0) return, in KES?","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('150dcf09-7d8a-53d5-8ef8-79be22cb1b2f', 'a3528aab-a33b-5689-bd81-bc5930b0cf42', 4, 'single_choice', '{"itemId":"i4-threshold-cell","text":"Why write =IF(B2<=C2,\"Reorder\",\"OK\") instead of =IF(B2<=25,\"Reorder\",\"OK\") when C2 holds 25?"}'::jsonb, '[{"id":"follows-data","label":"The flag updates when the reorder point in C2 changes"},{"id":"faster","label":"It calculates faster"},{"id":"required","label":"IF cannot compare with a typed number"},{"id":"no-difference","label":"There is no difference"}]'::jsonb, 1),
