  ('e4b3efe9-0517-5053-8ba1-27e7d6e705de', '4a241035-b7df-5707-b8c7-160751524b6a', 2, 'numeric', '{"itemId":"i2-sell-through","text":"C2 holds 180 units sold and B2 holds 240 units received. What does =IFERROR(C2/B2,0) return? Give the decimal.","answerHint":"A decimal, for example 0.4"}'::jsonb, null, 1),
