  ('58208f3b-9017-5f3f-a20c-c68b704cb67c', '6ec18b18-0a78-50fa-ae6c-0e91727b7cf9', 2, 'single_choice', '{"itemId":"l2-short-code","text":"Cell A2 holds SN-45-42. What does =IF(LEN(A2)=9,\"OK\",\"Check\") show?"}'::jsonb, '[{"id":"ok","label":"OK"},{"id":"check","label":"Check"},{"id":"eight","label":"8"},{"id":"error","label":"#VALUE!"}]'::jsonb, 1),
  ('9ab0ed88-73de-5ef6-86c1-f66690c44412', '6ec18b18-0a78-50fa-ae6c-0e91727b7cf9', 3, 'numeric', '{"itemId":"l3-len-number","text":"What does =LEN(1050) return?","answerHint":"Whole number"}'::jsonb, null, 1),
