  ('a8804849-0cd3-5e9b-936a-26ed21722414', '668faed6-be53-5d51-b3c1-db9dfd6dcca4', 1, 'numeric', '{"itemId":"l1-boot-price","text":"What does =XLOOKUP(\"bt-330\",$E$2:$E$6,$G$2:$G$6) return, in KES?","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('aa4d8426-aee2-5360-ab54-05ade98a2008', '668faed6-be53-5d51-b3c1-db9dfd6dcca4', 2, 'single_choice', '{"itemId":"l2-missing-code","text":"Gumboots (code GB-610) are not on the price list. What does =XLOOKUP(\"GB-610\",$E$2:$E$6,$G$2:$G$6) show?"}'::jsonb, '[{"id":"zero","label":"0"},{"id":"na","label":"#N/A"},{"id":"blank","label":"An empty cell"},{"id":"nearest","label":"The price of the closest code"}]'::jsonb, 1),
  ('01beb6b6-5226-55da-ac0f-4f04d2dc9d09', '668faed6-be53-5d51-b3c1-db9dfd6dcca4', 3, 'single_choice', '{"itemId":"l3-dollar-signs","text":"Why does the formula use $E$2:$E$6 rather than E2:E6?"}'::jsonb, '[{"id":"currency","label":"Because the prices are in KES"},{"id":"fixed","label":"So the price list stays the same when the formula is copied down"},{"id":"exact","label":"It turns on exact match"},{"id":"faster","label":"It makes the lookup faster"}]'::jsonb, 1),
