  ('e0e90c6c-4400-5311-81aa-bf1cc09e1078', '6379a10f-8739-5071-8169-113c4c527f8a', 4, 'numeric', '{"itemId":"c4-margin","text":"Retail price minus cost for SL-075 is the profit per pair. Look up both from the list and give the profit in KES.","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('bb27ec1a-6ff3-5e81-a5d8-ed496acb239b', '5a330004-ee6e-5458-a659-6ea232aa7ce5', 1, 'single_choice', '{"itemId":"e1-div0","text":"The code GB-610 is on the list, but its opening stock is 0. In the sheet, C2 holds that stock (0) and D2 holds the units sold, so D2/C2 shows #DIV/0!. Which tool replaces this #DIV/0! with n/a?"}'::jsonb, '[{"id":"notfound","label":"The if_not_found argument of XLOOKUP"},{"id":"iferror","label":"IFERROR around D2/C2"},{"id":"both","label":"Neither, #DIV/0! cannot be replaced"},{"id":"round","label":"ROUND"}]'::jsonb, 1),
  ('3b851529-33b8-533e-aa56-b8076caf2a11', '5a330004-ee6e-5458-a659-6ea232aa7ce5', 2, 'single_choice', '{"itemId":"e2-text-times","text":"ZZ-999 is not on the list. What does =XLOOKUP(\"ZZ-999\",$G$2:$G$6,$H$2:$H$6,\"Not listed\")*2 show?"}'::jsonb, '[{"id":"na","label":"#N/A"},{"id":"zero","label":"0"},{"id":"text","label":"Not listed"},{"id":"value","label":"#VALUE!"}]'::jsonb, 1),
  ('dd517dc0-f96e-5144-adb2-6bb350996199', '5a330004-ee6e-5458-a659-6ea232aa7ce5', 3, 'numeric', '{"itemId":"e3-sellthrough","text":"A product has opening stock of 48 and units sold of 36. Give the sell-through (units sold divided by opening stock) as a decimal, for example 0.5.","answerHint":"Decimal, for example 0.5"}'::jsonb, null, 1),
  ('b6e23401-c162-5f86-a6ad-cfd3da5457ee', '5a330004-ee6e-5458-a659-6ea232aa7ce5', 4, 'single_choice', '{"itemId":"e4-hidden-errors","text":"Why is it risky to wrap every formula on a sheet in IFERROR(..., \"n/a\")?"}'::jsonb, '[{"id":"slow","label":"It makes the file larger"},{"id":"numbers","label":"It turns numbers into text"},{"id":"hide","label":"It also hides real mistakes, such as a wrong range, so the problem is not noticed"},{"id":"case","label":"It makes text case-sensitive"}]'::jsonb, 1),
  ('2548446f-5172-59fe-8254-9defc5fc2866', '07de2e3b-3436-5e06-b580-134a2ed4c5f0', 1, 'numeric', '{"itemId":"h1-may-sales","text":"What does =XLOOKUP(\"May\",$B$1:$G$1,$B$2:$G$2) return, in K?","answerHint":"Whole number, in K"}'::jsonb, null, 1),
  ('ba330875-09dc-571b-ba12-e111d62191d1', '07de2e3b-3436-5e06-b580-134a2ed4c5f0', 2, 'single_choice', '{"itemId":"h2-shape","text":"What does =XLOOKUP(\"Mar\",$B$1:$G$1,$A$2:$A$7) show, where $A$2:$A$7 is a column of 6 cells?"}'::jsonb, '[{"id":"value","label":"#VALUE!, because a row lookup range needs a row return range"},{"id":"mar","label":"The value for March from column A"},{"id":"na","label":"#N/A, because Mar is not in the list"},{"id":"zero","label":"0"}]'::jsonb, 1),
  ('e58ab03f-ddc5-5fa9-a1de-9d72415da6d2', '07de2e3b-3436-5e06-b580-134a2ed4c5f0', 3, 'numeric', '{"itemId":"h3-april-variance","text":"Variance is sales minus target. What is the variance for April, in K? Use a minus sign if it is negative.","answerHint":"Whole number, in K"}'::jsonb, null, 1),
  ('f40baae3-b9e0-5574-be83-14b8e97f4f9a', '07de2e3b-3436-5e06-b580-134a2ed4c5f0', 4, 'single_choice', '{"itemId":"h4-mixed-ref","text":"Why is the month written as B$5 in the formula in B6, then copied across to C6 and D6?"}'::jsonb, '[{"id":"row","label":"The $ keeps the row at 5, while the column moves to C5 and D5"},{"id":"col","label":"The $ keeps the column at B"},{"id":"money","label":"The $ shows the result is money"},{"id":"fast","label":"It makes the formula faster"}]'::jsonb, 1),
  ('b83f6b61-9c32-5f69-8ffd-ac66be755567', '08d78722-f9f5-5dfe-b1d2-64702f6697a3', 1, 'numeric', '{"itemId":"m1-margin-kes","text":"What is the margin in KES for SD-120 (price minus cost)?","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('ed3a2232-4863-5dc7-a968-674147a7453a', '08d78722-f9f5-5dfe-b1d2-64702f6697a3', 2, 'numeric', '{"itemId":"m2-margin-pct","text":"What is the margin percentage of SL-075 (margin divided by price), to 1 decimal place? Give the answer as a percentage, for example 52.2.","answerHint":"Percentage, 1 decimal place"}'::jsonb, null, 1),
  ('c80f045d-248c-5a00-9f08-0da33aa3ddc0', '08d78722-f9f5-5dfe-b1d2-64702f6697a3', 3, 'numeric', '{"itemId":"m3-markup-pct","text":"What is the mark-up percentage of SN-450 (margin divided by cost), to 1 decimal place? Give the answer as a percentage, for example 12.3.","answerHint":"Percentage, 1 decimal place"}'::jsonb, null, 1),
  ('59fc29de-8e6a-506b-ac04-82c5ea2e796a', '08d78722-f9f5-5dfe-b1d2-64702f6697a3', 4, 'single_choice', '{"itemId":"m4-formula","text":"In the sheet, B2 holds the cost, C2 the price and D2 the margin in KES. Which formula gives the margin percentage on the selling price?"}'::jsonb, '[{"id":"cost","label":"=D2/B2"},{"id":"price","label":"=D2/C2"},{"id":"share","label":"=B2/C2"},{"id":"flip","label":"=C2/D2"}]'::jsonb, 1),
  ('45b21840-a058-50ce-8330-83f7bc865082', '7fe43471-16d9-54b8-96a5-a9903fd07e72', 1, 'numeric', '{"itemId":"s1-run-size-40","text":"What does =XLOOKUP(40,$F$2:$F$10,$G$2:$G$10) return? Give the number of pairs in the size run.","answerHint":"Whole number of pairs"}'::jsonb, null, 1),
  ('aedf7bb9-0fc6-5dff-b6bb-c1e508ce3744', '7fe43471-16d9-54b8-96a5-a9903fd07e72', 2, 'single_choice', '{"itemId":"s2-text-size","text":"In an order line, the size wanted was typed as text, ''39, and the size table holds the number 39. What does XLOOKUP return?"}'::jsonb, '[{"id":"na","label":"#N/A, because the text 39 does not match the number 39"},{"id":"found","label":"The row for size 39, because the digits are the same"},{"id":"zero","label":"0, because the value is text"},{"id":"nearest","label":"The row for size 40, the closest number"}]'::jsonb, 1),
  ('d16ecf85-ca97-5b19-a1c6-6e16ab13b936', '7fe43471-16d9-54b8-96a5-a9903fd07e72', 3, 'numeric', '{"itemId":"s3-run-value","text":"One size run of size 43 is ordered. Value it at the unit price: pairs in run multiplied by the price. Give the answer in KES.","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('3bb8bc86-3706-5a5d-943c-cc93374e4e2f', '7fe43471-16d9-54b8-96a5-a9903fd07e72', 4, 'single_choice', '{"itemId":"s4-new-size","text":"A customer asks for size 47, which is not in the table. You add it in a new row 11. The formulas still use $F$2:$F$10. What should you do so size 47 is found?"}'::jsonb, '[{"id":"fallback","label":"Change the fourth argument to \"Found\""},{"id":"extend","label":"Add the size 47 row to the table and extend the ranges to row 11"},{"id":"format","label":"Format the size cell as a number"},{"id":"nothing","label":"Nothing, XLOOKUP reads the whole sheet"}]'::jsonb, 1),
  ('b6dab632-bad6-5ec1-b628-944f99d76217', '3bf443da-bf6e-5e6e-b9c1-ac47a9d4abb5', 1, 'numeric', '{"itemId":"i1-margin","text":"A pair costs KES 600 and sells for KES 800. What is its margin, as a percentage? Type 25 for 25%.","answerHint":"A percentage, for example 25 for 25%"}'::jsonb, null, 1),
  ('8969cd5e-ac3e-5089-9d20-601462997c35', '3bf443da-bf6e-5e6e-b9c1-ac47a9d4abb5', 2, 'numeric', '{"itemId":"i2-markup","text":"The same pair costs KES 600 and sells for KES 800. What is its mark-up, as a percentage to 1 decimal place?","answerHint":"A percentage to 1 decimal place, for example 12.5"}'::jsonb, null, 1),
  ('0285a7be-c7f2-5902-a60b-ed27cd35719b', '3bf443da-bf6e-5e6e-b9c1-ac47a9d4abb5', 3, 'numeric', '{"itemId":"i3-price","text":"A pair costs KES 400 and the buyer applies a 50% mark-up on cost. What is the selling price, in KES?","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('5af96d99-4a65-5238-9709-106c53c88876', '3bf443da-bf6e-5e6e-b9c1-ac47a9d4abb5', 4, 'single_choice', '{"itemId":"i4-difference","text":"Why is the margin of a profitable item always lower than its mark-up?"}'::jsonb, '[{"id":"bigger-base","label":"Margin divides the profit by the price, which is bigger than the cost that mark-up divides by"},{"id":"tax","label":"Margin has tax taken off and mark-up does not"},{"id":"same","label":"It is not: margin is always higher than mark-up"},{"id":"rounding","label":"It is only a rounding effect"}]'::jsonb, 1),
  ('abd15631-ca88-55d2-b894-0bf2344ea1b3', 'c4e97e8b-eff8-591c-aed4-1b71be711e28', 1, 'numeric', '{"itemId":"i1-median-odd","text":"Weekly sales in K for five weeks are 12, 15, 11, 90 and 14. What is the MEDIAN, in K?","answerHint":"Whole number, in K"}'::jsonb, null, 1),
  ('475c2bbb-3f84-5132-99a8-7d44d2964450', 'c4e97e8b-eff8-591c-aed4-1b71be711e28', 2, 'numeric', '{"itemId":"i2-median-even","text":"Weekly sales in K for four weeks are 100, 120, 130 and 900. What is the MEDIAN, in K?","answerHint":"Whole number, in K"}'::jsonb, null, 1),
  ('28743a6d-3ee9-52c4-bdc0-650ec134596c', 'c4e97e8b-eff8-591c-aed4-1b71be711e28', 3, 'single_choice', '{"itemId":"i3-which-figure","text":"A store sells about KES 120K in most weeks, but one week had a KES 540K bulk order. Which figure best describes a typical week?"}'::jsonb, '[{"id":"average","label":"The average, because it uses every week"},{"id":"median","label":"The median, because the bulk order does not drag it upwards"},{"id":"max","label":"The maximum, because it shows what the store can do"},{"id":"sum","label":"The total, because it is the largest number"}]'::jsonb, 1),
  ('8be86b94-2691-5233-8909-f78a0e4b2772', 'c4e97e8b-eff8-591c-aed4-1b71be711e28', 4, 'single_choice', '{"itemId":"i4-outlier-grows","text":"In a list of eight weekly sales, the biggest value is changed from 540 to 5,400. What happens?"}'::jsonb, '[{"id":"both-rise","label":"Both the average and the median rise a lot"},{"id":"median-same","label":"The average rises a lot, but the median stays the same"},{"id":"avg-same","label":"The median rises a lot, but the average stays the same"},{"id":"neither","label":"Neither changes"}]'::jsonb, 1),
  ('2783c281-dae8-5904-8eae-a7a9f8577e45', 'd567629e-bb0a-51d9-8bb6-ec6d85649681', 1, 'numeric', '{"itemId":"i1-commission-amount","text":"Using the tier table in the training (2% from 0, 4% from 50,000, 6% from 100,000), a rep sells KES 64,000. How much commission, in KES, does the rep earn?","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('5521b508-91eb-5526-b802-763812696ba9', 'd567629e-bb0a-51d9-8bb6-ec6d85649681', 2, 'single_choice', '{"itemId":"i2-boundary","text":"A rep sells exactly KES 50,000. With the formula =IF(B2>=$F$4,$G$4,IF(B2>=$F$3,$G$3,$G$2)), which rate does the rep get?"}'::jsonb, '[{"id":"two","label":"2%, the first tier"},{"id":"four","label":"4%, the middle tier"},{"id":"six","label":"6%, the top tier"},{"id":"error","label":"An error, because 50,000 is on the boundary"}]'::jsonb, 1),
  ('8527553b-3d11-5f11-8075-ccf7a8cc657d', 'd567629e-bb0a-51d9-8bb6-ec6d85649681', 3, 'single_choice', '{"itemId":"i3-order","text":"Why does the formula test the highest tier (>= $F$4) first?"}'::jsonb, '[{"id":"first-true","label":"IF stops at the first test that is TRUE, so testing the lowest tier first would give everyone the lowest rate"},{"id":"faster","label":"Excel calculates the largest numbers faster"},{"id":"required","label":"Excel only accepts tiers listed from highest to lowest"},{"id":"no-reason","label":"The order makes no difference to the result"}]'::jsonb, 1),
  ('7beef852-c444-5124-b8e9-b74f2946bcd5', 'd567629e-bb0a-51d9-8bb6-ec6d85649681', 4, 'numeric', '{"itemId":"i4-count-ifs","text":"A new plan has 5 commission tiers. How many IF functions does the nested formula need?","answerHint":"A whole number"}'::jsonb, null, 1),
  ('2137f993-63e3-5bbd-a7f0-7253c0ec0dc7', 'c294536a-bacb-59d8-a728-c70300ee44f8', 1, 'single_choice', '{"itemId":"i1-not-result","text":"What does =NOT(5>3) return?"}'::jsonb, '[{"id":"choice-a","label":"FALSE"},{"id":"choice-b","label":"TRUE"},{"id":"five","label":"5"},{"id":"error","label":"#VALUE!"}]'::jsonb, 1),
  ('e4e6e493-24e6-5aaa-bb6e-8840e515a6e8', 'c294536a-bacb-59d8-a728-c70300ee44f8', 2, 'single_choice', '{"itemId":"i2-same-as-not","text":"Which formula gives the same answer as =NOT(D2=\"Core\")?"}'::jsonb, '[{"id":"not-equal","label":"=D2<>\"Core\""},{"id":"equal-not-core","label":"=D2=\"Not Core\""},{"id":"greater","label":"=D2>\"Core\""},{"id":"minus","label":"=-D2=\"Core\""}]'::jsonb, 1),
  ('5a159110-6189-514b-927e-c9aa39ecca26', 'c294536a-bacb-59d8-a728-c70300ee44f8', 3, 'numeric', '{"itemId":"i3-count-clearance","text":"Rule: Clearance when the range is not Core AND (weeks in store is at least 12 OR sell-through is below 30%) AND the line is not yet marked down. Line 1: Seasonal, 13 weeks, 40%, not marked down. Line 2: Core, 30 weeks, 5%, not marked down. Line 3: Seasonal, 6 weeks, 29%, already marked down. Line 4: Seasonal, 3 weeks, 29%, not marked down. How many lines go on clearance?","answerHint":"A whole number"}'::jsonb, null, 1),
  ('59c2763d-3498-5061-9dc9-090d28904838', 'c294536a-bacb-59d8-a728-c70300ee44f8', 4, 'single_choice', '{"itemId":"i4-exclude-marked-down","text":"Which test, placed inside AND, keeps a line out of clearance when E2 says \"Yes\" (already marked down)?"}'::jsonb, '[{"id":"not-yes","label":"NOT(E2=\"Yes\")"},{"id":"is-yes","label":"E2=\"Yes\""},{"id":"or-yes","label":"OR(E2,\"Yes\")"},{"id":"not-no","label":"NOT(E2=\"No\")"}]'::jsonb, 1),
  ('31eea004-e406-5fb1-9164-788629afba86', '1a02c6c7-b0ed-5943-b283-2bb4daf1e122', 1, 'single_choice', '{"itemId":"i1-or-result","text":"What does =OR(1>2,3>2) return?"}'::jsonb, '[{"id":"choice-a","label":"TRUE"},{"id":"choice-b","label":"FALSE"},{"id":"three","label":"3"},{"id":"error","label":"#VALUE!"}]'::jsonb, 1),
  ('0c31a2cf-a9f6-5f3f-b6f1-914f463707ac', '1a02c6c7-b0ed-5943-b283-2bb4daf1e122', 2, 'numeric', '{"itemId":"i2-count-included","text":"Rule: include a store when the region is Nairobi OR weekly sales are above 500K. Store 1: Nairobi, 300K. Store 2: Mombasa, 520K. Store 3: Kisumu, 500K. Store 4: Nakuru, 100K. How many stores are included?","answerHint":"A whole number"}'::jsonb, null, 1),
  ('261095c3-9cda-532b-a978-ed49aa556066', '1a02c6c7-b0ed-5943-b283-2bb4daf1e122', 3, 'single_choice', '{"itemId":"i3-choose","text":"You want to flag stores that have low sales or low sell-through, or both. Which function belongs inside IF?"}'::jsonb, '[{"id":"or","label":"OR, because one low measure is enough"},{"id":"and","label":"AND, because both measures must be low"},{"id":"not","label":"NOT, because we are flagging bad stores"},{"id":"sum","label":"SUM, because two measures are added"}]'::jsonb, 1),
  ('3004bd9c-809c-59ea-a769-ec9f6df17415', '1a02c6c7-b0ed-5943-b283-2bb4daf1e122', 4, 'single_choice', '{"itemId":"i4-syntax","text":"Which formula correctly shows Include for Nairobi stores or sales above 500K, where region is in B2 and sales in C2?"}'::jsonb, '[{"id":"ok","label":"=IF(OR(B2=\"Nairobi\",C2>500),\"Include\",\"Skip\")"},{"id":"word","label":"=IF(B2=\"Nairobi\" OR C2>500,\"Include\",\"Skip\")"},{"id":"no-quotes","label":"=IF(OR(B2=Nairobi,C2>500),\"Include\",\"Skip\")"},{"id":"single","label":"=IF(OR(C2>500),\"Include\",\"Skip\")"}]'::jsonb, 1),
  ('60516e95-7206-5d2d-8d2b-862822147ca0', '9702389d-7cd9-5aee-8719-e35454dded1e', 1, 'numeric', '{"itemId":"i1-precedence","text":"What does =10+2*3^2 return?","answerHint":"A whole number"}'::jsonb, null, 1),
  ('833513eb-f6c9-5be6-8f46-965a2a2bb168', '9702389d-7cd9-5aee-8719-e35454dded1e', 2, 'single_choice', '{"itemId":"i2-minus-power","text":"What does =-3^2 return in Excel?"}'::jsonb, '[{"id":"nine","label":"9"},{"id":"minus-nine","label":"-9"},{"id":"minus-six","label":"-6"},{"id":"error","label":"#NUM!"}]'::jsonb, 1),
  ('289239d5-f82d-5c49-abc6-854db2a6aa73', '9702389d-7cd9-5aee-8719-e35454dded1e', 3, 'numeric', '{"itemId":"i3-percent","text":"What does =100+10% return? Type the number exactly, including the decimal.","answerHint":"A number with a decimal point"}'::jsonb, null, 1),
  ('d3b2d2b6-4590-5cc2-a9e5-72e348831749', '9702389d-7cd9-5aee-8719-e35454dded1e', 4, 'single_choice', '{"itemId":"i4-loaded-cost","text":"C2 is the unit cost, E2 the duty rate, D2 the freight for the whole order and B2 the number of pairs. Which formula gives the unit cost plus duty, plus freight per pair?"}'::jsonb, '[{"id":"choice-a","label":"=C2*(1+E2)+D2/B2"},{"id":"no-brackets","label":"=C2*1+E2+D2/B2"},{"id":"all-in-brackets","label":"=C2*(1+E2+D2)/B2"},{"id":"freight-times-duty","label":"=C2*1+E2*D2/B2"}]'::jsonb, 1),
  ('af33e907-77ca-547f-a652-712fb77c12b0', 'b0e05ecb-319f-5648-8cbd-4f23aa347546', 1, 'numeric', '{"itemId":"o1-line-total","text":"A line orders 8 pairs of SS-210. What does =XLOOKUP(\"SS-210\",$F$2:$F$7,$H$2:$H$7)*8 return, in KES?","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('fa9b58ed-cab3-593a-a883-56b8ed623432', 'b0e05ecb-319f-5648-8cbd-4f23aa347546', 2, 'numeric', '{"itemId":"o2-order-total","text":"An order has 5 pairs of SD-120, 2 pairs of BT-330 and 10 pairs of SL-075. What is the order total in KES?","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('96e54138-5748-5d27-9028-a4dfccfc8422', 'b0e05ecb-319f-5648-8cbd-4f23aa347546', 3, 'single_choice', '{"itemId":"o3-missing-code","text":"One line in an order has a code that is not in the price list, and there is no fourth argument. The other four lines are fine. What does =SUM(D2:D6) show?"}'::jsonb, '[{"id":"partial","label":"The total of the four good lines"},{"id":"zero","label":"0"},{"id":"na","label":"#N/A"},{"id":"blank","label":"An empty cell"}]'::jsonb, 1),
  ('830d86a3-a7ca-5769-bdb4-cd1a7b29ff88', 'b0e05ecb-319f-5648-8cbd-4f23aa347546', 4, 'single_choice', '{"itemId":"o4-why-lookup","text":"Why use XLOOKUP for the price instead of typing the price into each line formula?"}'::jsonb, '[{"id":"faster","label":"Typed prices are not allowed in Excel"},{"id":"update","label":"When the price list changes, every line total updates by itself"},{"id":"round","label":"XLOOKUP rounds the prices"},{"id":"sort","label":"XLOOKUP sorts the order"}]'::jsonb, 1),
  ('ef174260-3cb5-5be8-b580-9c3c765e8f55', '7184da1c-9407-51bb-ac3e-468886cb03f0', 1, 'single_choice', '{"itemId":"i1-charm-formula","text":"D2 holds a discounted price. Which formula gives a charm price that ends in 9, for example 1609?"}'::jsonb, '[{"id":"round-then-minus","label":"=ROUND(D2,-1)-1"},{"id":"minus-then-round","label":"=ROUND(D2-1,-1)"},{"id":"round-then-plus","label":"=ROUND(D2,-1)+1"},{"id":"round-whole","label":"=ROUND(D2,0)-1"}]'::jsonb, 1),
  ('552cc9f6-e55d-52c1-b37b-4af7ca32e9cf', '7184da1c-9407-51bb-ac3e-468886cb03f0', 2, 'numeric', '{"itemId":"i2-charm-numeric","text":"A discounted price in D2 is KES 2,287. What does =ROUND(D2,-1)-1 return, in KES?","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('41c9b91c-9e2e-5c50-8ef3-515025de97dd', '7184da1c-9407-51bb-ac3e-468886cb03f0', 3, 'numeric', '{"itemId":"i3-full-chain","text":"A pair of shoes has a list price of KES 1,850 in B2. With a 10% discount, what does =ROUND(B2*(1-10%),-1)-1 return, in KES?","answerHint":"Whole number, in KES"}'::jsonb, null, 1),
  ('9a83ef1c-5f20-5de2-959d-785474972c44', '7184da1c-9407-51bb-ac3e-468886cb03f0', 4, 'single_choice', '{"itemId":"i4-discount-cell","text":"Your D2:F5 formulas all point at the discount in $B$7. The discount in B7 changes from 15% to 20%. What happens?"}'::jsonb, '[{"id":"all-update","label":"Every discounted, rounded and charm price recalculates"},{"id":"only-d","label":"Only the discounted prices in column D change"},{"id":"nothing","label":"Nothing changes until the formulas are retyped"},{"id":"error","label":"The sheet shows #REF!"}]'::jsonb, 1),
  ('5037c4a4-0b68-5aea-9fb5-ae29d059d35b', '8d73fcdc-ec7f-52f4-9aa1-f8d44d449897', 1, 'numeric', '{"itemId":"i1-shortfall","text":"A style sells 20 pairs a week. The target is 8 weeks of cover, with 70 pairs on hand and 30 on order. How many pairs should you reorder?","answerHint":"Whole number of pairs"}'::jsonb, null, 1),
  ('f86d71bf-558e-579a-acbd-a41652488223', '8d73fcdc-ec7f-52f4-9aa1-f8d44d449897', 2, 'numeric', '{"itemId":"i2-floor","text":"A style sells 15 pairs a week. The target is 6 weeks, with 100 pairs on hand and none on order. What does =MAX(0,6*15-100-0) return?","answerHint":"Whole number of pairs"}'::jsonb, null, 1),
  ('e9ced879-e5b5-5f4b-85fc-37f2e920f6e1', '8d73fcdc-ec7f-52f4-9aa1-f8d44d449897', 3, 'single_choice', '{"itemId":"i3-why-max","text":"Why wrap the shortfall in MAX(0, ...)?"}'::jsonb, '[{"id":"negative","label":"A style that is already overstocked gives a negative number, and MAX turns that into 0 pairs"},{"id":"round","label":"It rounds the order up to a whole case"},{"id":"double","label":"It doubles the quantity for safety"},{"id":"text","label":"It changes the number into text"}]'::jsonb, 1),
  ('a249f256-c85f-5386-9a7f-fd38b15b23c9', '8d73fcdc-ec7f-52f4-9aa1-f8d44d449897', 4, 'single_choice', '{"itemId":"i4-on-order","text":"Why subtract the pairs already on order as well as the pairs on hand?"}'::jsonb, '[{"id":"no-double-order","label":"Stock on its way will arrive soon, so ordering for it again would buy the same pairs twice"},{"id":"cheaper","label":"Pairs on order are cheaper"},{"id":"optional","label":"It is optional, because on-order pairs never arrive"},{"id":"sold","label":"Pairs on order have already been sold"}]'::jsonb, 1),
  ('06666e83-d280-5deb-9f4d-2ded9f5e99cb', 'cf91abca-bf8b-5af7-bdc5-354d107f4892', 1, 'numeric', '{"itemId":"l1-right-times-two","text":"What does =RIGHT(\"SN-450-42\",2)*2 return?","answerHint":"Whole number"}'::jsonb, null, 1),
