  ('7f32beb8-b605-5442-ab25-6b9701efee8f', 'cf91abca-bf8b-5af7-bdc5-354d107f4892', 3, 'single_choice', '{"itemId":"l3-lookup-text","text":"The size list in F2:F7 holds the numbers 38 to 43. What does =XLOOKUP(RIGHT(\"SN-450-42\",2),F2:F7,G2:G7) show?"}'::jsonb, '[{"id":"na","label":"#N/A"},{"id":"pairs","label":"The pairs in stock for size 42"},{"id":"zero","label":"0"},{"id":"value","label":"#VALUE!"}]'::jsonb, 1),
