  ('362bdb7a-3434-51ac-92c0-ecf76a3480f8', '2e6c80c4-f6ec-597b-8881-c40a9f649756', 1, 'numeric', '{"itemId":"i1-negative-digits","text":"What does =ROUND(2374.25,-2) return?","answerHint":"Whole number"}'::jsonb, null, 1),
  ('35345e0e-b95d-52b8-a0a8-da20023f7da9', '2e6c80c4-f6ec-597b-8881-c40a9f649756', 2, 'single_choice', '{"itemId":"i2-what-negative-does","text":"What does a negative digits argument, such as the -1 in =ROUND(B2,-1), do?"}'::jsonb, '[{"id":"left","label":"It rounds to tens, hundreds and so on, to the left of the decimal point"},{"id":"choice-b","label":"It keeps extra decimal places"},{"id":"sign","label":"It turns the answer negative"},{"id":"error","label":"It causes an error"}]'::jsonb, 1),
  ('15ab2eb9-77d2-5a57-aa01-fea704f503a4', '2e6c80c4-f6ec-597b-8881-c40a9f649756', 3, 'numeric', '{"itemId":"i3-sum-rounded","text":"B2, B3 and B4 each hold 10.4. C2, C3 and C4 each hold =ROUND(B2,0), =ROUND(B3,0) and =ROUND(B4,0). What does =SUM(C2:C4) return?","answerHint":"Whole number"}'::jsonb, null, 1),
  ('0020c480-6d6e-5ef2-a772-b72a28dcb86b', '2e6c80c4-f6ec-597b-8881-c40a9f649756', 4, 'single_choice', '{"itemId":"i4-half","text":"What does =ROUND(2.5,0) return?"}'::jsonb, '[{"id":"three","label":"3"},{"id":"two","label":"2"},{"id":"two-five","label":"2.5"},{"id":"error","label":"#VALUE!"}]'::jsonb, 1),
  ('bb769532-5070-5688-9647-a2155e6149b3', 'aec3eb27-f5a5-502d-9962-358084a41cdd', 1, 'numeric', '{"itemId":"i1-sumifs","text":"Cells A2:A4 hold Nairobi, Mombasa, Nairobi and C2:C4 hold 100, 80, 50 (sales in K). What does =SUMIFS(C2:C4,A2:A4,\"Nairobi\") return, in K?","answerHint":"Whole number, in K"}'::jsonb, null, 1),
  ('7efc7de9-f776-5291-bf7a-532d54125a60', 'aec3eb27-f5a5-502d-9962-358084a41cdd', 2, 'numeric', '{"itemId":"i2-countifs","text":"A store''s four weekly sales in K are 120, 95, 100 and 130. How many weeks does =COUNTIFS(C2:C5,\">=\"&100) count?","answerHint":"Whole number of weeks"}'::jsonb, null, 1),
  ('4815ab39-97a5-50fa-a3d9-1cee9d2ee550', 'aec3eb27-f5a5-502d-9962-358084a41cdd', 3, 'single_choice', '{"itemId":"i3-xlookup","text":"Why fetch each store''s target with XLOOKUP instead of typing the target into the scorecard?"}'::jsonb, '[{"id":"follows-table","label":"The target comes from the table by store name, so one change in the table updates the scorecard"},{"id":"faster","label":"Typed numbers are not allowed in Excel"},{"id":"rounds","label":"XLOOKUP rounds the target to 1 decimal place"},{"id":"sorts","label":"XLOOKUP sorts the stores from best to worst"}]'::jsonb, 1),
  ('7f739dd5-d323-5b29-8a24-8bea0f5e0c2e', 'aec3eb27-f5a5-502d-9962-358084a41cdd', 4, 'single_choice', '{"itemId":"i4-rating","text":"Rules: Star needs achievement at or above 100% AND at least 3 good weeks; otherwise Watch if achievement is at least 90%; otherwise Action. A store has achievement 102% and 2 good weeks. What rating does =IF(AND(L2>=100,J2>=3),\"Star\",IF(L2>=90,\"Watch\",\"Action\")) give?"}'::jsonb, '[{"id":"star","label":"Star"},{"id":"watch","label":"Watch"},{"id":"action","label":"Action"},{"id":"error","label":"#VALUE!"}]'::jsonb, 1),
  ('de216463-0c62-54ad-8dbe-d3df34dcbfbc', '5298a606-8563-532b-9abe-c1902bb242b6', 1, 'numeric', '{"itemId":"i1-basic","text":"A style sold 48 pairs and has 112 pairs on hand. Using sold / (sold + on hand), what is the sell-through %, to 1 decimal place?","answerHint":"Number, 1 decimal place, without the % sign"}'::jsonb, null, 1),
  ('73ac30ea-44a3-5e0f-806a-02c99e41ad39', '5298a606-8563-532b-9abe-c1902bb242b6', 2, 'numeric', '{"itemId":"i2-rounding","text":"A style sold 25 pairs and has 50 on hand. What does =ROUND(25/(25+50)*100,1) return?","answerHint":"Number, 1 decimal place"}'::jsonb, null, 1),
  ('a8983f8c-fe6c-58f6-9207-cf3d4ae3f856', '5298a606-8563-532b-9abe-c1902bb242b6', 3, 'single_choice', '{"itemId":"i3-iferror","text":"Why wrap the sell-through formula in IFERROR(...,0)?"}'::jsonb, '[{"id":"new-line","label":"A new style with no stock makes sold + on hand equal 0, and IFERROR replaces the #DIV/0! error with 0"},{"id":"faster","label":"It makes the sheet calculate faster"},{"id":"round","label":"It rounds the answer to 1 decimal place"},{"id":"negative","label":"It stops sell-through from going above 100%"}]'::jsonb, 1),
  ('68b99679-5040-57dd-960e-524e0afbd831', '5298a606-8563-532b-9abe-c1902bb242b6', 4, 'single_choice', '{"itemId":"i4-boundary","text":"The slow-seller limit in G2 is 40. A style has a sell-through of exactly 40.0 in D2. What does =IF(D2<$G$2,\"Slow\",\"OK\") return?"}'::jsonb, '[{"id":"slow","label":"Slow"},{"id":"ok","label":"OK"},{"id":"choice-c","label":"FALSE"},{"id":"error","label":"#DIV/0!"}]'::jsonb, 1),
  ('b3e6ef9c-43f4-5e9b-897a-9e053d7f8660', '89ff94fb-259f-5632-88a0-23e98d2fc347', 1, 'numeric', '{"itemId":"i1-share","text":"Regional sales add up to a total of 2,000K and Kisumu sold 350K. What is Kisumu''s share of the total, as a percentage? Type 25 for 25%.","answerHint":"A percentage, for example 25 for 25%"}'::jsonb, null, 1),
  ('fbbc9ffe-3864-5fbe-9600-c9fd2710ecfb', '89ff94fb-259f-5632-88a0-23e98d2fc347', 2, 'single_choice', '{"itemId":"i2-decimal","text":"A share cell shows 0.4. What share of the total is that?"}'::jsonb, '[{"id":"forty","label":"40%"},{"id":"four","label":"4%"},{"id":"point-four","label":"0.4%"},{"id":"four-hundred","label":"400%"}]'::jsonb, 1),
  ('36a0be98-128f-513a-97dc-84bc6fc545fd', '89ff94fb-259f-5632-88a0-23e98d2fc347', 3, 'single_choice', '{"itemId":"i3-absolute","text":"The total is in B7. You write =B2/B7 in C2 and copy it down to C3. What goes wrong?"}'::jsonb, '[{"id":"moves","label":"C3 becomes =B3/B8, which divides by an empty cell and gives #DIV/0!"},{"id":"nothing","label":"Nothing, the formula copies correctly"},{"id":"doubles","label":"C3 shows double the correct share"},{"id":"blank","label":"C3 stays empty"}]'::jsonb, 1),
  ('914e480b-023d-53ab-b158-924eb83df2d8', '89ff94fb-259f-5632-88a0-23e98d2fc347', 4, 'numeric', '{"itemId":"i4-missing-share","text":"Four regions have shares of 0.4, 0.2, 0.15 and a fourth region that completes the total. What is the fourth share, as a decimal?","answerHint":"A decimal, for example 0.1"}'::jsonb, null, 1),
  ('16df080e-3380-50af-ac4f-333a6baa058f', '0f89c724-01ca-53b2-8926-deb5fdb447c5', 1, 'numeric', '{"itemId":"i1-share","text":"Size 41 sold 62 pairs out of 250 pairs in total. What is its share of the total, as a %?","answerHint":"Number, 1 decimal place, without the % sign"}'::jsonb, null, 1),
  ('e62eb4d7-bc22-5798-aae8-9929a0f14daf', '0f89c724-01ca-53b2-8926-deb5fdb447c5', 2, 'numeric', '{"itemId":"i2-share-other","text":"A size sold 90 pairs out of 400 in total. What does =ROUND(90/400*100,1) return?","answerHint":"Number, 1 decimal place"}'::jsonb, null, 1),
  ('46f2952d-ed66-52de-8d7e-7a18d0c9304a', '0f89c724-01ca-53b2-8926-deb5fdb447c5', 3, 'single_choice', '{"itemId":"i3-absolute","text":"In C2 you write =B2/$B$9*100 and copy it down to C8. What does the $ in $B$9 do?"}'::jsonb, '[{"id":"locks","label":"It keeps every row pointing at the same total cell"},{"id":"dollars","label":"It formats the answer as dollars"},{"id":"multiplies","label":"It multiplies the answer by 9"},{"id":"nothing","label":"Nothing, it is only decoration"}]'::jsonb, 1),
  ('ef510f1a-635c-52a4-af7f-a1b956702638', '0f89c724-01ca-53b2-8926-deb5fdb447c5', 4, 'single_choice', '{"itemId":"i4-tie","text":"Sizes 41 and 42 both sold 62 pairs, and 62 is the maximum. What does =XLOOKUP(MAX(B2:B8),B2:B8,A2:A8) return, when size 41 is above size 42 in the list?"}'::jsonb, '[{"id":"first","label":"41, because XLOOKUP returns the first match"},{"id":"last","label":"42, because XLOOKUP returns the last match"},{"id":"both","label":"Both sizes together"},{"id":"error","label":"An error, because of the tie"}]'::jsonb, 1),
  ('44d8a5b1-c26f-5e2b-846b-fe597c29515b', '59a42d53-b1f2-5568-99ac-a7d555a0ed20', 1, 'single_choice', '{"itemId":"l1-pad-result","text":"What does =RIGHT(\"000\"&45,3) return?"}'::jsonb, '[{"id":"pad","label":"045"},{"id":"plain","label":"45"},{"id":"zeros","label":"00045"},{"id":"tail","label":"000"}]'::jsonb, 1),
  ('9a2af917-fba3-5eaf-9787-9388b1797cdf', '59a42d53-b1f2-5568-99ac-a7d555a0ed20', 2, 'single_choice', '{"itemId":"l2-why-pad","text":"Why does the key formula join \"000\" in front of the style number before using RIGHT?"}'::jsonb, '[{"id":"fixed-width","label":"So every style number has exactly three characters, with leading zeros where needed"},{"id":"bigger","label":"To make the style number three times bigger"},{"id":"unique","label":"To make every key unique"},{"id":"text","label":"Because RIGHT cannot read numbers"}]'::jsonb, 1),
  ('a9a7c1e3-c182-583c-ae5c-ac023b149eb6', '59a42d53-b1f2-5568-99ac-a7d555a0ed20', 3, 'numeric', '{"itemId":"l3-countif-keys","text":"What does =COUNTIF(D2:D6,\"SNE-450-42\") return for the key list in Training?","answerHint":"Whole number"}'::jsonb, null, 1),
  ('fd18e03f-215b-5d78-9d22-6b95ac5939e2', '59a42d53-b1f2-5568-99ac-a7d555a0ed20', 4, 'single_choice', '{"itemId":"l4-greater-than-one","text":"Why does the duplicate check test COUNTIF(...)>1 and not COUNTIF(...)>0?"}'::jsonb, '[{"id":"self","label":"Because every key is counted once for itself, so a count of 1 means the key is unique"},{"id":"excel","label":"Because COUNTIF starts counting at zero"},{"id":"range","label":"Because the range has one blank cell"},{"id":"text","label":"Because >0 only works on numbers"}]'::jsonb, 1),
  ('01e509bd-f036-5819-88fd-f8360218b3c1', '69b47fca-5302-5645-9c03-eeaf92a8dfa5', 1, 'single_choice', '{"itemId":"i1-order","text":"Why does =IF(B2=0,\"Out of stock\",IF(B2<C2,\"Low\", ...)) test B2=0 before B2<C2?"}'::jsonb, '[{"id":"zero-first","label":"Zero is also below the minimum, so the Low test would catch it first and hide Out of stock"},{"id":"faster","label":"Excel calculates the first test faster"},{"id":"alphabet","label":"Excel checks the labels in alphabetical order"},{"id":"required","label":"IF cannot start with a less-than test"}]'::jsonb, 1),
  ('d5a8ed20-98e9-5afc-bccd-348d6ecd1993', '69b47fca-5302-5645-9c03-eeaf92a8dfa5', 2, 'numeric', '{"itemId":"i2-count-ok","text":"Minimum 10 and maximum 40 for every line. Stock on hand: 0, 10, 45, 5, 40. How many lines are labelled OK by AND(B2>=C2,B2<=D2)?","answerHint":"A whole number"}'::jsonb, null, 1),
  ('49579e9f-13c0-52f1-bbff-b8e5ad8041be', '69b47fca-5302-5645-9c03-eeaf92a8dfa5', 3, 'single_choice', '{"itemId":"i3-and-boundary","text":"On hand (B2) is 50, minimum (C2) is 10 and maximum (D2) is 50. What does =AND(B2>=C2,B2<=D2) return?"}'::jsonb, '[{"id":"choice-a","label":"TRUE"},{"id":"choice-b","label":"FALSE"},{"id":"ok","label":"OK"},{"id":"fifty","label":"50"}]'::jsonb, 1),
  ('09910dfd-5353-53e9-bb2e-1e13be36e2f0', '69b47fca-5302-5645-9c03-eeaf92a8dfa5', 4, 'single_choice', '{"itemId":"i4-status","text":"Stock on hand is 8, minimum 10 and maximum 50. Which label does =IF(B2=0,\"Out of stock\",IF(AND(B2>=C2,B2<=D2),\"OK\",IF(B2<C2,\"Low\",\"Overstock\"))) show?"}'::jsonb, '[{"id":"low","label":"Low"},{"id":"ok","label":"OK"},{"id":"out","label":"Out of stock"},{"id":"over","label":"Overstock"}]'::jsonb, 1),
  ('b5cc7a24-9ff0-5b00-abb9-bca82050d5b5', 'c3cd76fd-6299-50d0-b3b0-32fcd4a302b1', 1, 'numeric', '{"itemId":"i1-cover","text":"A style has 240 pairs on hand and sells 30 pairs a week. How many weeks of cover is that?","answerHint":"Number of weeks"}'::jsonb, null, 1),
  ('1e1721cc-3ab2-5b4c-b621-30a7bb069c74', 'c3cd76fd-6299-50d0-b3b0-32fcd4a302b1', 2, 'numeric', '{"itemId":"i2-cover-rounded","text":"A style has 95 pairs on hand and sells 40 a week. What does =ROUND(95/40,1) return?","answerHint":"Number, 1 decimal place"}'::jsonb, null, 1),
  ('90dc46a8-103d-5c70-9160-4ec59e7fe86c', 'c3cd76fd-6299-50d0-b3b0-32fcd4a302b1', 3, 'single_choice', '{"itemId":"i3-iferror-text","text":"Why use IFERROR(ROUND(B2/C2,1),\"No sales\") instead of the plain division?"}'::jsonb, '[{"id":"zero","label":"When weekly sales are 0 the division gives #DIV/0!, and IFERROR turns that into a readable message"},{"id":"round","label":"Because IFERROR rounds the result"},{"id":"faster","label":"Because it makes the cover number larger"},{"id":"negative","label":"Because it stops stock on hand going negative"}]'::jsonb, 1),
  ('3ceeea2e-fa6b-503b-b0c1-42a74fbdf002', 'c3cd76fd-6299-50d0-b3b0-32fcd4a302b1', 4, 'single_choice', '{"itemId":"i4-double-sales","text":"A style sells twice as fast as before, and stock on hand stays the same. What happens to its cover in weeks?"}'::jsonb, '[{"id":"doubles","label":"It doubles"},{"id":"halves","label":"It halves"},{"id":"same","label":"It stays the same"},{"id":"zero","label":"It becomes zero"}]'::jsonb, 1),
  ('bb3e51bc-1289-5729-bda8-82f34d056240', '748c0a4a-aa6f-5198-948b-e45da6477844', 1, 'single_choice', '{"itemId":"s1-range-12-months","text":"Monthly sales for a full year sit in B2 to B13. Which formula gives the yearly total?"}'::jsonb, '[{"id":"sum-range","label":"=SUM(B2:B13)"},{"id":"sum-two-cells","label":"=SUM(B2,B13)"},{"id":"add-two-cells","label":"=B2+B13"},{"id":"typed","label":"Type the total from a calculator"}]'::jsonb, 1),
  ('bdbb94be-cccd-53ec-871c-32a73af101e9', '748c0a4a-aa6f-5198-948b-e45da6477844', 2, 'numeric', '{"itemId":"s2-kisumu-total","text":"A Kisumu store sold school shoes worth 45K in January, 62K in February and 38K in March (B2:B4). What does =SUM(B2:B4) return, in K?","answerHint":"Whole number, in K"}'::jsonb, null, 1),
  ('42f1f2a5-bdd6-5020-a6e7-1dc54e9ebe6e', '748c0a4a-aa6f-5198-948b-e45da6477844', 3, 'single_choice', '{"itemId":"s3-copy-right","text":"B5 contains =SUM(B2:B4). You copy B5 into C5. What formula does C5 contain?"}'::jsonb, '[{"id":"same","label":"=SUM(B2:B4)"},{"id":"shifted","label":"=SUM(C2:C4)"},{"id":"down","label":"=SUM(B3:B5)"},{"id":"value","label":"The number from B5"}]'::jsonb, 1),
