  ('91020330-f29a-5e3f-b43f-599bde1f2e57', '1c51b82a-a3c7-51f9-843b-5c2765dffb25', 1, 'numeric', '{"itemId":"l1-mombasa-total","text":"What does =SUMIF(B2:B7,\"Mombasa\",C2:C7) return, in K?","answerHint":"Whole number, in K"}'::jsonb, null, 1),
  ('69af4e99-ebc8-582b-a0bb-ed11c4f133f1', '1c51b82a-a3c7-51f9-843b-5c2765dffb25', 2, 'numeric', '{"itemId":"l2-lower-case","text":"What does =SUMIF(B2:B7,\"nairobi\",C2:C7) return, in K?","answerHint":"Whole number, in K"}'::jsonb, null, 1),
  ('032cdfb9-66e5-5f0c-863f-090e70673087', '1c51b82a-a3c7-51f9-843b-5c2765dffb25', 3, 'single_choice', '{"itemId":"l3-arguments","text":"In =SUMIF(B2:B7,\"Kisumu\",C2:C7), what is the job of C2:C7?"}'::jsonb, '[{"id":"where-to-look","label":"It is the list SUMIF searches for the word Kisumu"},{"id":"numbers-to-add","label":"It holds the numbers that are added for the matching rows"},{"id":"count-rows","label":"It counts how many rows match"},{"id":"second-region","label":"It is a second region to include in the total"}]'::jsonb, 1),
  ('dc42f286-ec4d-5bb7-8c64-ebfd70304ea9', '1c51b82a-a3c7-51f9-843b-5c2765dffb25', 4, 'single_choice', '{"itemId":"l4-cell-criteria","text":"Why is it useful to write =SUMIF($B$2:$B$7,E2,$C$2:$C$7) with the region in cell E2?"}'::jsonb, '[{"id":"copy-down","label":"You can copy the formula down and E3, E4 give the other regions"},{"id":"faster","label":"Excel calculates cell references faster than text"},{"id":"case","label":"It makes the match case sensitive"},{"id":"wildcards","label":"It lets you use * to match several regions"}]'::jsonb, 1),
  ('5d4b7755-0d07-5b61-8c9a-ddfe542f9fc6', 'eed05573-ea1b-52fe-b33d-6b8dfe1484fd', 1, 'numeric', '{"itemId":"l1-at-least-100","text":"What does =SUMIF(C2:C7,\">=100\") return, in K?","answerHint":"Whole number, in K"}'::jsonb, null, 1),
